input.command:
mkdir -p oha_impl/src
cat <<'EOF' > oha_impl/src/main.rs
mod args;
mod client;
mod printer;
mod result_data;
mod tui;

use anyhow::Result;
use args::{Args, OutputFormat};
use clap::Parser;

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    // Handle dump-urls
    if let Some(dump_count) = args.dump_urls {
        let url_generator = client::UrlGenerator::new(&args)?;
        for _ in 0..dump_count {
            println!("{}", url_generator.generate()?);
        }
        return Ok(());
    }

    // Handle debug mode
    if args.debug {
        client::debug_request(&args).await?;
        return Ok(());
    }

    // Run the load test
    let result = if args.no_tui {
        client::run_no_tui(&args).await?
    } else {
        tui::run_tui(&args).await?
    };

    // Output results
    let output = match args.output_format {
        OutputFormat::Text => printer::format_text(&result, &args),
        OutputFormat::Json => printer::format_json(&result)?,
        OutputFormat::Csv => printer::format_csv(&result),
        OutputFormat::Quiet => String::new(),
    };

    if !output.is_empty() {
        if let Some(ref output_path) = args.output {
            std::fs::write(output_path, &output)?;
        } else {
            print!("{}", output);
        }
    }

    // Write to sqlite db if specified
    if let Some(ref db_url) = args.db_url {
        client::write_to_db(&result, db_url)?;
    }

    Ok(())
}
EOF

