cat <<'ARGS_EOF' > oha_impl/src/args.rs
use clap::{Parser, ValueEnum};
use std::time::Duration;
use anyhow::{Result, anyhow};

#[derive(Clone, Debug, ValueEnum)]
pub enum OutputFormat {
    Text,
    Json,
    Csv,
    Quiet,
}

#[derive(Clone, Debug, ValueEnum)]
pub enum TimeUnit {
    Ns,
    Us,
    Ms,
    S,
    M,
    H,
}

#[derive(Debug, Clone, Parser)]
#[command(name = "oha", about = "Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.", version = "1.12.1")]
pub struct Args {
    /// Target URL or file with multiple URLs.
    #[arg(value_name = "URL", required_unless_present_any = ["dump_urls"])]
    pub url: Option<String>,

    /// Number of requests to run. Accepts plain numbers or suffixes: k = 1,000, m = 1,000,000 (e.g. 10k, 1m).
    #[arg(short = 'n', value_name = "N_REQUESTS", default_value = "200", value_parser = parse_requests)]
    pub n_requests: Option<usize>,

    /// Number of connections to run concurrently. You may should increase limit to number of open files for larger `-c`.
    #[arg(short = 'c', value_name = "N_CONNECTIONS", default_value = "50")]
    pub n_connections: usize,

    /// Number of parallel requests to send on HTTP/2. `oha` will run c * p concurrent workers in total.
    #[arg(short = 'p', value_name = "N_HTTP2_PARALLEL", default_value = "1")]
    pub n_http2_parallel: usize,

    /// Duration of application to send requests.
    #[arg(short = 'z', value_name = "DURATION", value_parser = parse_duration_str)]
    pub duration: Option<Duration>,

    /// When the duration is reached, ongoing requests are waited
    #[arg(short = 'w', long = "wait-ongoing-requests-after-deadline")]
    pub wait_ongoing_requests_after_deadline: bool,

    /// Rate limit for all, in queries per second (QPS)
    #[arg(short = 'q', value_name = "QUERY_PER_SECOND")]
    pub query_per_second: Option<f64>,

    /// Introduce delay between a predefined number of requests.
    #[arg(long = "burst-delay", value_name = "BURST_DURATION", value_parser = parse_duration_str)]
    pub burst_delay: Option<Duration>,

    /// Rates of requests for burst. Default is 1
    #[arg(long = "burst-rate", value_name = "BURST_REQUESTS")]
    pub burst_rate: Option<usize>,

    /// Generate URL by rand_regex crate but dot is disabled for each query
    #[arg(long = "rand-regex-url")]
    pub rand_regex_url: bool,

    /// Read the URLs to query from a file
    #[arg(long = "urls-from-file")]
    pub urls_from_file: bool,

    /// A parameter for the '--rand-regex-url'. The max_repeat parameter gives the maximum extra repeat counts the x*, x+ and x{n,} operators will become.
    #[arg(long = "max-repeat", value_name = "MAX_REPEAT", default_value = "4")]
    pub max_repeat: u32,

    /// Dump target Urls <DUMP_URLS> times to debug --rand-regex-url
    #[arg(long = "dump-urls", value_name = "DUMP_URLS")]
    pub dump_urls: Option<usize>,

    /// Correct latency to avoid coordinated omission problem. It's ignored if -q is not set.
    #[arg(long = "latency-correction")]
    pub latency_correction: bool,

    /// No realtime tui
    #[arg(long = "no-tui")]
    pub no_tui: bool,

    /// Frame per second for tui.
    #[arg(long = "fps", default_value = "16")]
    pub fps: u64,

    /// HTTP method
    #[arg(short = 'm', long = "method", value_name = "METHOD", default_value = "GET")]
    pub method: String,

    /// Custom HTTP header. Examples: -H "foo: bar"
    #[arg(short = 'H', value_name = "HEADERS")]
    pub headers: Vec<String>,

    /// Custom Proxy HTTP header. Examples: --proxy-header "foo: bar"
    #[arg(long = "proxy-header", value_name = "PROXY_HEADERS")]
    pub proxy_headers: Vec<String>,

    /// Timeout for each request. Default to infinite.
    #[arg(short = 't', value_name = "TIMEOUT", value_parser = parse_duration_str)]
    pub timeout: Option<Duration>,

    /// Timeout for establishing a new connection. Default to 5s.
    #[arg(long = "connect-timeout", value_name = "CONNECT_TIMEOUT", default_value = "5s", value_parser = parse_duration_str)]
    pub connect_timeout: Option<Duration>,

    /// HTTP Accept Header.
    #[arg(short = 'A', value_name = "ACCEPT_HEADER")]
    pub accept_header: Option<String>,

    /// HTTP request body.
    #[arg(short = 'd', value_name = "BODY_STRING")]
    pub body_string: Option<String>,

    /// HTTP request body from file.
    #[arg(short = 'D', value_name = "BODY_PATH")]
    pub body_path: Option<std::path::PathBuf>,

    /// HTTP request body from file line by line.
    #[arg(short = 'Z', value_name = "BODY_PATH_LINES")]
    pub body_path_lines: Option<std::path::PathBuf>,

    /// Specify HTTP multipart POST data (curl compatible). Examples: -F 'name=value' -F 'file=@path/to/file'
    #[arg(short = 'F', long = "form", value_name = "FORM")]
    pub form: Vec<String>,

    /// Content-Type.
    #[arg(short = 'T', value_name = "CONTENT_TYPE")]
    pub content_type: Option<String>,

    /// Basic authentication (username:password), or AWS credentials (access_key:secret_key)
    #[arg(short = 'a', value_name = "BASIC_AUTH")]
    pub basic_auth: Option<String>,

    /// AWS session token
    #[arg(long = "aws-session", value_name = "AWS_SESSION")]
    pub aws_session: Option<String>,

    /// AWS SigV4 signing params (format: aws:amz:region:service)
    #[arg(long = "aws-sigv4", value_name = "AWS_SIGV4")]
    pub aws_sigv4: Option<String>,

    /// HTTP proxy
    #[arg(short = 'x', value_name = "PROXY")]
    pub proxy: Option<String>,

    /// HTTP version to connect to proxy. Available values 0.9, 1.0, 1.1, 2.
    #[arg(long = "proxy-http-version", value_name = "PROXY_HTTP_VERSION")]
    pub proxy_http_version: Option<String>,

    /// Use HTTP/2 to connect to proxy. Shorthand for --proxy-http-version=2
    #[arg(long = "proxy-http2")]
    pub proxy_http2: bool,

    /// HTTP version. Available values 0.9, 1.0, 1.1, 2, 3
    #[arg(long = "http-version", value_name = "HTTP_VERSION")]
    pub http_version: Option<String>,

    /// Use HTTP/2. Shorthand for --http-version=2
    #[arg(long = "http2")]
    pub http2: bool,

    /// HTTP Host header
    #[arg(long = "host", value_name = "HOST")]
    pub host: Option<String>,

    /// Disable compression.
    #[arg(long = "disable-compression")]
    pub disable_compression: bool,

    /// Limit for number of Redirect. Set 0 for no redirection.
    #[arg(short = 'r', long = "redirect", value_name = "REDIRECT", default_value = "10")]
    pub redirect: usize,

    /// Disable keep-alive
    #[arg(long = "disable-keepalive")]
    pub disable_keepalive: bool,

    /// *Not* perform a DNS lookup at beginning to cache it
    #[arg(long = "no-pre-lookup")]
    pub no_pre_lookup: bool,

    /// Lookup only ipv6.
    #[arg(long = "ipv6")]
    pub ipv6: bool,

    /// Lookup only ipv4.
    #[arg(long = "ipv4")]
    pub ipv4: bool,

    /// (TLS) Use the specified certificate file to verify the peer.
    #[arg(long = "cacert", value_name = "CACERT")]
    pub cacert: Option<std::path::PathBuf>,

    /// (TLS) Use the specified client certificate file.
    #[arg(long = "cert", value_name = "CERT")]
    pub cert: Option<std::path::PathBuf>,

    /// (TLS) Use the specified client key file.
    #[arg(long = "key", value_name = "KEY")]
    pub key: Option<std::path::PathBuf>,

    /// Accept invalid certs.
    #[arg(long = "insecure")]
    pub insecure: bool,

    /// Override DNS resolution and default port numbers
    #[arg(long = "connect-to", value_name = "CONNECT_TO")]
    pub connect_to: Vec<String>,

    /// Disable the color scheme.
    #[arg(long = "no-color", env = "NO_COLOR")]
    pub no_color: bool,

    /// Connect to a unix socket instead of the domain in the URL.
    #[arg(long = "unix-socket", value_name = "UNIX_SOCKET")]
    pub unix_socket: Option<String>,

    /// Include a response status code successful or not successful breakdown
    #[arg(long = "stats-success-breakdown")]
    pub stats_success_breakdown: bool,

    /// Write succeeded requests to sqlite database url
    #[arg(long = "db-url", value_name = "DB_URL")]
    pub db_url: Option<String>,

    /// Perform a single request and dump the request and response
    #[arg(long = "debug")]
    pub debug: bool,

    /// Output file to write the results to.
    #[arg(short = 'o', long = "output", value_name = "OUTPUT")]
    pub output: Option<std::path::PathBuf>,

    /// Output format
    #[arg(long = "output-format", value_name = "OUTPUT_FORMAT", default_value = "text")]
    pub output_format: OutputFormat,

    /// Time unit to be used.
    #[arg(short = 'u', long = "time-unit", value_name = "TIME_UNIT")]
    pub time_unit: Option<TimeUnit>,
}

fn parse_requests(s: &str) -> Result<usize, String> {
    let s = s.trim();
    if let Some(num) = s.strip_suffix('k').or_else(|| s.strip_suffix('K')) {
        num.parse::<usize>().map(|n| n * 1_000).map_err(|e| e.to_string())
    } else if let Some(num) = s.strip_suffix('m').or_else(|| s.strip_suffix('M')) {
        num.parse::<usize>().map(|n| n * 1_000_000).map_err(|e| e.to_string())
    } else {
        s.parse::<usize>().map_err(|e| e.to_string())
    }
}

fn parse_duration_str(s: &str) -> Result<Duration, String> {
    humantime::parse_duration(s).map_err(|e| e.to_string())
}

impl Args {
    pub fn get_url(&self) -> &str {
        self.url.as_deref().unwrap_or("")
    }
}
ARGS_EOF

