cat <<'EOF' > oha_impl/src/result_data.rs
use std::collections::HashMap;
use std::time::Duration;

#[derive(Debug, Clone)]
pub struct RequestResult {
    pub start_time: f64,  // seconds from start of test
    pub dns_lookup: f64,  // seconds
    pub dialup: f64,      // seconds (dns+dialup total)
    pub response_delay: f64, // seconds from connection to first byte
    pub duration: f64,    // total request duration in seconds
    pub bytes: usize,
    pub status: Option<u16>,
    pub error: Option<String>,
}

#[derive(Debug, Clone)]
pub struct LoadTestResult {
    pub total_duration: f64,   // seconds
    pub request_results: Vec<RequestResult>,
}

impl LoadTestResult {
    pub fn success_results(&self) -> Vec<&RequestResult> {
        self.request_results.iter()
            .filter(|r| r.status.map(|s| s >= 200 && s < 300).unwrap_or(false))
            .collect()
    }

    pub fn successful_durations(&self) -> Vec<f64> {
        self.success_results().iter().map(|r| r.duration).collect()
    }

    pub fn all_durations(&self) -> Vec<f64> {
        self.request_results.iter()
            .filter(|r| r.status.is_some())
            .map(|r| r.duration)
            .collect()
    }

    pub fn success_rate(&self) -> f64 {
        let total = self.request_results.len();
        if total == 0 {
            return 0.0;
        }
        let success = self.success_results().len();
        success as f64 / total as f64
    }

    pub fn total_bytes(&self) -> usize {
        self.success_results().iter().map(|r| r.bytes).sum()
    }

    pub fn status_code_distribution(&self) -> HashMap<u16, usize> {
        let mut map = HashMap::new();
        for r in &self.request_results {
            if let Some(status) = r.status {
                *map.entry(status).or_insert(0) += 1;
            }
        }
        map
    }

    pub fn error_distribution(&self) -> HashMap<String, usize> {
        let mut map = HashMap::new();
        for r in &self.request_results {
            if let Some(ref err) = r.error {
                *map.entry(err.clone()).or_insert(0) += 1;
            }
        }
        map
    }
}
