        builder = builder.connection_verbose(true).tcp_keepalive(None).pool_max_idle_per_host(0);
    }

    // HTTP2
    if args.http2 || args.http_version.as_deref() == Some("2") {
        builder = builder.http2_prior_knowledge();
    }

    // Proxy
    if let Some(ref proxy_url) = args.proxy {
        let proxy = reqwest::Proxy::all(proxy_url)?;
        builder = builder.proxy(proxy);
    }

    // IPv4/IPv6
    if args.ipv4 {
        builder = builder.local_address(std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED));
    }

    // User-agent
    builder = builder.user_agent("oha/1.12.1");

    // CA cert
    if let Some(ref cacert_path) = args.cacert {
        let cert_pem = std::fs::read(cacert_path)?;
        let cert = reqwest::Certificate::from_pem(&cert_pem)?;
        builder = builder.add_root_certificate(cert);
    }

    // Client cert + key
    if let (Some(ref cert_path), Some(ref key_path)) = (&args.cert, &args.key) {
        let cert_pem = std::fs::read(cert_path)?;
        let key_pem = std::fs::read(key_path)?;
        let identity_pem = [cert_pem, key_pem].concat();
        let identity = reqwest::Identity::from_pem(&identity_pem)?;
        builder = builder.identity(identity);
    }

    Ok(builder.build()?)
}

fn apply_headers(mut builder: reqwest::RequestBuilder, args: &Args) -> Result<reqwest::RequestBuilder> {
    // Custom headers
    for h in &args.headers {
        if let Some(pos) = h.find(':') {
            let key = h[..pos].trim();
            let val = h[pos+1..].trim();
            builder = builder.header(key, val);
        }
    }

    // Accept header
    if let Some(ref accept) = args.accept_header {
        builder = builder.header("Accept", accept.as_str());
    }

    // Content-Type
    if let Some(ref ct) = args.content_type {
        builder = builder.header("Content-Type", ct.as_str());
    }

    // Host header
    if let Some(ref host) = args.host {
        builder = builder.header("Host", host.as_str());
    }

    // Basic auth
    if let Some(ref auth) = args.basic_auth {
        if let Some(pos) = auth.find(':') {
            let user = &auth[..pos];
            let pass = &auth[pos+1..];
            builder = builder.basic_auth(user, Some(pass));
        }
    }

    Ok(builder)
}

async fn do_request(
    client: &Client,
    args: &Args,
    url_str: &str,
    start_offset: f64,
    body_lines: &Option<Arc<Mutex<Box<dyn Iterator<Item=Vec<u8>> + Send>>>>,
) -> RequestResult {
    let method = Method::from_bytes(args.method.as_bytes())
        .unwrap_or(Method::GET);

    let request_start = Instant::now();

    let mut req_builder = client.request(method, url_str);

    // Apply headers
    match apply_headers(req_builder, args) {
        Ok(rb) => { req_builder = rb; }
        Err(_) => {}
    }

    // Body
    if let Some(ref body) = args.body_string {
        req_builder = req_builder.body(body.clone());
    } else if let Some(ref body_path) = args.body_path {
        if let Ok(data) = std::fs::read(body_path) {
            req_builder = req_builder.body(data);
        }
    }

    let t0 = Instant::now();
    let result = req_builder.send().await;

    match result {
        Ok(response) => {
            let status = response.status().as_u16();
            let dns_lookup = 0.0; // reqwest doesn't expose this directly
            let dialup = t0.elapsed().as_secs_f64();

            let response_start = Instant::now();

            let bytes_result = response.bytes().await;
            let total_time = t0.elapsed().as_secs_f64();

            match bytes_result {
                Ok(bytes) => {
                    RequestResult {
                        start_time: start_offset,
                        dns_lookup: 0.0,
                        dialup: dialup,
                        response_delay: response_start.elapsed().as_secs_f64(),
                        duration: total_time,
                        bytes: bytes.len(),
                        status: Some(status),
                        error: None,
                    }
                }
                Err(e) => {
                    RequestResult {
                        start_time: start_offset,
                        dns_lookup: 0.0,
                        dialup: dialup,
                        response_delay: 0.0,
                        duration: total_time,
                        bytes: 0,
                        status: None,
                        error: Some(format!("{}", e)),
                    }
                }
            }
        }
        Err(e) => {
            let total_time = t0.elapsed().as_secs_f64();
            RequestResult {
                start_time: start_offset,
                dns_lookup: 0.0,
                dialup: 0.0,
                response_delay: 0.0,
                duration: total_time,
                bytes: 0,
                status: None,
                error: Some(format!("{}", e)),
            }
        }
    }
}

pub async fn run_no_tui(args: &Args) -> Result<LoadTestResult> {
    let url_generator = Arc::new(UrlGenerator::new(args)?);
    let client = Arc::new(build_client(args)?);

    let n_requests = args.n_requests.unwrap_or(200);
    let n_connections = args.n_connections;

    let results = Arc::new(Mutex::new(Vec::new()));
    let test_start = Instant::now();

    if let Some(duration) = args.duration {
        // Time-based test
        let deadline = test_start + duration;

        let mut handles = vec![];
        for _ in 0..n_connections {
            let client = client.clone();
            let args_url = args.get_url().to_string();
            let url_gen = url_generator.clone();
            let results = results.clone();
            let args_clone = args.clone();

            let handle = tokio::spawn(async move {
                loop {
                    if Instant::now() >= deadline {
                        break;
                    }
                    let url = match url_gen.generate() {
                        Ok(u) => u,
                        Err(_) => break,
                    };
                    let offset = test_start.elapsed().as_secs_f64();
                    let r = do_request(&client, &args_clone, &url, offset, &None).await;
                    results.lock().await.push(r);
                }
            });
            handles.push(handle);
        }

        for h in handles {
            let _ = h.await;
        }
    } else {
        // Request count based test
        let counter = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        let mut handles = vec![];
        for _ in 0..n_connections {
            let client = client.clone();
            let url_gen = url_generator.clone();
            let results = results.clone();
            let counter = counter.clone();
            let args_clone = args.clone();

            let handle = tokio::spawn(async move {
                loop {
                    let cur = counter.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    if cur >= n_requests {
                        break;
                    }
                    let url = match url_gen.generate() {
                        Ok(u) => u,
                        Err(_) => break,
                    };
                    let offset = test_start.elapsed().as_secs_f64();
                    let r = do_request(&client, &args_clone, &url, offset, &None).await;
                    results.lock().await.push(r);
                }
            });
            handles.push(handle);
        }

        for h in handles {
            let _ = h.await;
        }
    }

    let total_duration = test_start.elapsed().as_secs_f64();
    let request_results = results.lock().await.clone();

    Ok(LoadTestResult {
        total_duration,
        request_results,
    })
}

pub fn write_to_db(result: &LoadTestResult, db_url: &str) -> Result<()> {
    let conn = rusqlite::Connection::open(db_url)?;
    conn.execute_batch("CREATE TABLE IF NOT EXISTS requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        start_time REAL,
        dns_lookup REAL,
        dialup REAL,
        response_delay REAL,
        duration REAL,
        bytes INTEGER,
        status INTEGER
    )")?;

    for r in &result.request_results {
        if r.status.is_some() {
            conn.execute(
                "INSERT INTO requests (start_time, dns_lookup, dialup, response_delay, duration, bytes, status) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                rusqlite::params![r.start_time, r.dns_lookup, r.dialup, r.response_delay, r.duration, r.bytes, r.status],
            )?;
        }
    }

    Ok(())
}
