fn determine_time_unit(args: &Args, durations: &[f64], total: f64) -> TimeUnitEnum {
    if let Some(ref unit) = args.time_unit {
        match unit {
            TimeUnit::Ns => return TimeUnitEnum::Ns,
            TimeUnit::Us => return TimeUnitEnum::Us,
            TimeUnit::Ms => return TimeUnitEnum::Ms,
            TimeUnit::S => return TimeUnitEnum::S,
            TimeUnit::M => return TimeUnitEnum::M,
            TimeUnit::H => return TimeUnitEnum::H,
        }
    }

    // Auto-determine based on average duration
    let avg = if durations.is_empty() {
        total
    } else {
        durations.iter().sum::<f64>() / durations.len() as f64
    };

    if avg.is_nan() || avg <= 0.0 {
        // Use total duration as reference
        let t = total;
        if t < 0.001 { TimeUnitEnum::Ns }
        else if t < 1.0 { TimeUnitEnum::Ms }
        else if t < 60.0 { TimeUnitEnum::S }
        else { TimeUnitEnum::M }
    } else if avg < 0.000001 { TimeUnitEnum::Ns }
    else if avg < 0.001 { TimeUnitEnum::Us }
    else if avg < 1.0 { TimeUnitEnum::Ms }
    else if avg < 60.0 { TimeUnitEnum::S }
    else { TimeUnitEnum::M }
}

#[derive(Clone)]
enum TimeUnitEnum {
    Ns, Us, Ms, S, M, H
}

fn get_time_unit_info(unit: &TimeUnitEnum) -> (&'static str, f64) {
    match unit {
        TimeUnitEnum::Ns => ("ns", 1e9),
        TimeUnitEnum::Us => ("us", 1e6),
        TimeUnitEnum::Ms => ("ms", 1e3),
        TimeUnitEnum::S => ("s", 1.0),
        TimeUnitEnum::M => ("m", 1.0 / 60.0),
        TimeUnitEnum::H => ("h", 1.0 / 3600.0),
    }
}

fn format_duration(secs: f64, unit: &TimeUnitEnum) -> String {
    if secs.is_nan() {
        let (name, _) = get_time_unit_info(unit);
        return format!("NaN {}", name);
    }
    if secs.is_infinite() {
        let (name, _) = get_time_unit_info(unit);
        if secs > 0.0 {
            return format!("inf {}", name);
        } else {
            return format!("-inf {}", name);
        }
    }

    let (name, multiplier) = get_time_unit_info(unit);
    let val = secs * multiplier;

    match unit {
        TimeUnitEnum::Ns => format!("{:.4} {}", val, name),
        _ => format!("{:.4} {}", val, name),
    }
}

fn format_bytes(bytes: usize) -> String {
    if bytes == 0 {
        return "0 B".to_string();
    }
    let f = bytes as f64;
    if f < 1024.0 {
        format!("{} B", bytes)
    } else if f < 1024.0 * 1024.0 {
        format!("{:.2} KiB", f / 1024.0)
    } else if f < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.2} MiB", f / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", f / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_bytes_f(bytes: f64) -> String {
    if bytes <= 0.0 {
        return "0 B".to_string();
    }
    if bytes < 1024.0 {
        format!("{:.0} B", bytes)
    } else if bytes < 1024.0 * 1024.0 {
        format!("{:.2} KiB", bytes / 1024.0)
    } else if bytes < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.2} MiB", bytes / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_size_per_req(size: f64) -> String {
    if size.is_nan() {
        return "NaN".to_string();
    }
    if size < 1024.0 {
        format!("{:.0} B", size)
    } else if size < 1024.0 * 1024.0 {
        format!("{:.2} KiB", size / 1024.0)
    } else {
        format!("{:.2} MiB", size / (1024.0 * 1024.0))
    }
}

fn format_histogram(durations: &[f64], unit: &TimeUnitEnum, title: &str) -> String {
    let mut out = format!("{}\n", title);

    const NUM_BUCKETS: usize = 11;

    if durations.is_empty() {
        let nan_label = format_duration(f64::NAN, unit);
        for _ in 0..NUM_BUCKETS {
            out += &format!("  {:>10} [0] |\n", nan_label);
        }
        return out;
    }

    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let min = sorted[0];
    let max = sorted[sorted.len() - 1];

    let range = max - min;
    let bucket_size = if range == 0.0 { 1.0 } else { range / (NUM_BUCKETS as f64 - 1.0) };

    let mut buckets = vec![0usize; NUM_BUCKETS];
    let mut bucket_labels = vec![0.0f64; NUM_BUCKETS];

    for i in 0..NUM_BUCKETS {
        bucket_labels[i] = min + (i as f64) * bucket_size;
    }

    for &d in durations {
        if range == 0.0 {
            buckets[0] += 1;
        } else {
            let idx = ((d - min) / bucket_size).floor() as usize;
            let idx = idx.min(NUM_BUCKETS - 1);
            buckets[idx] += 1;
        }
    }

    let max_count = *buckets.iter().max().unwrap_or(&0);

    for i in 0..NUM_BUCKETS {
        let label = format_duration(bucket_labels[i], unit);
        let count = buckets[i];
        let bar = if max_count > 0 {
            let bar_len = (count as f64 / max_count as f64 * 32.0).round() as usize;
            "■".repeat(bar_len)
        } else {
            String::new()
        };
        out += &format!("  {:>10} [{}] |{}\n", label, count, bar);
    }

    out
}

fn format_distribution(durations: &[f64], unit: &TimeUnitEnum, title: &str) -> String {
    let mut out = format!("{}\n", title);

    let percentiles = [10.0, 25.0, 50.0, 75.0, 90.0, 95.0, 99.0, 99.9, 99.99];

    if durations.is_empty() {
        for &p in &percentiles {
            out += &format!("  {:.2}% in {}\n", p, format_duration(f64::NAN, unit));
        }
        return out;
    }

    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    for &p in &percentiles {
        let val = percentile(&sorted, p);
        out += &format!("  {:.2}% in {}\n", p, format_duration(val, unit));
    }

    out
}

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return f64::NAN;
    }
    let idx = (p / 100.0 * sorted.len() as f64).ceil() as usize;
    let idx = idx.min(sorted.len()) - 1;
    sorted[idx.max(0)]
}

pub fn format_json(result: &LoadTestResult) -> Result<String> {
    use serde_json::{json, Value};

    let durations = result.all_durations();
    let total = result.total_duration;
    let success_rate = result.success_rate();
    let total_bytes = result.total_bytes();

    let (fastest, slowest, average) = if durations.is_empty() {
        (f64::INFINITY, f64::NEG_INFINITY, f64::NAN)
    } else {
        let mut sorted = durations.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let fastest = sorted[0];
        let slowest = sorted[sorted.len() - 1];
        let avg = sorted.iter().sum::<f64>() / sorted.len() as f64;
        (fastest, slowest, avg)
    };

    let n_success = result.success_results().len();
    let requests_per_sec = result.request_results.len() as f64 / total;
    let size_per_req = if n_success == 0 { 0.0 } else { total_bytes as f64 / n_success as f64 };
    let size_per_sec = total_bytes as f64 / total;

    // Build response time histogram as map
    let hist = build_histogram_map(&durations);

    // Build percentiles
    let percentile_map = build_percentile_map(&durations);

    // RPS statistics  
    let rps_stats = compute_rps_stats(result);

    // DNS details
    let (dns_dialup_avg, dns_dialup_fast, dns_dialup_slow) = compute_dns_dialup(result);
    let (dns_lookup_avg, dns_lookup_fast, dns_lookup_slow) = compute_dns_lookup(result);

    let status_dist = result.status_code_distribution();
    let status_obj: serde_json::Map<String, Value> = status_dist.iter()
        .map(|(k, v)| (k.to_string(), json!(v)))
        .collect();

    let err_dist = result.error_distribution();
    let err_obj: serde_json::Map<String, Value> = err_dist.iter()
        .map(|(k, v)| (k.clone(), json!(v)))
        .collect();

    let output = json!({
        "summary": {
            "successRate": success_rate,
            "total": total,
            "slowest": slowest,
            "fastest": fastest,
            "average": average,
            "requestsPerSec": requests_per_sec,
            "totalData": total_bytes,
            "sizePerRequest": size_per_req as usize,
            "sizePerSec": size_per_sec
        },
        "responseTimeHistogram": hist,
        "latencyPercentiles": percentile_map,
        "rps": rps_stats,
        "details": {
            "DNSDialup": {
                "average": dns_dialup_avg,
                "fastest": dns_dialup_fast,
                "slowest": dns_dialup_slow
            },
            "DNSLookup": {
                "average": dns_lookup_avg,
                "fastest": dns_lookup_fast,
                "slowest": dns_lookup_slow
            }
        },
        "statusCodeDistribution": status_obj,
        "errorDistribution": err_obj
    });

    Ok(serde_json::to_string_pretty(&output)?)
}

fn build_histogram_map(durations: &[f64]) -> serde_json::Map<String, serde_json::Value> {
    let mut map = serde_json::Map::new();

    const NUM_BUCKETS: usize = 11;

    if durations.is_empty() {
        return map;
    }

    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let min = sorted[0];
    let max = sorted[sorted.len() - 1];
    let range = max - min;
    let bucket_size = if range == 0.0 { 0.0 } else { range / (NUM_BUCKETS as f64 - 1.0) };

    let mut buckets = vec![0usize; NUM_BUCKETS];
    let mut bucket_labels = vec![0.0f64; NUM_BUCKETS];

    for i in 0..NUM_BUCKETS {
        bucket_labels[i] = min + (i as f64) * bucket_size;
    }

    for &d in durations {
        if range == 0.0 {
            buckets[0] += 1;
        } else {
            let idx = ((d - min) / bucket_size).floor() as usize;
            let idx = idx.min(NUM_BUCKETS - 1);
            buckets[idx] += 1;
        }
    }

    for i in 0..NUM_BUCKETS {
        map.insert(bucket_labels[i].to_string(), serde_json::json!(buckets[i]));
    }

    map
}

fn build_percentile_map(durations: &[f64]) -> serde_json::Value {
    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    serde_json::json!({
        "p10": percentile(&sorted, 10.0),
        "p25": percentile(&sorted, 25.0),
        "p50": percentile(&sorted, 50.0),
        "p75": percentile(&sorted, 75.0),
        "p90": percentile(&sorted, 90.0),
        "p95": percentile(&sorted, 95.0),
        "p99": percentile(&sorted, 99.0),
        "p99.9": percentile(&sorted, 99.9),
        "p99.99": percentile(&sorted, 99.99)
    })
}

fn compute_rps_stats(result: &LoadTestResult) -> serde_json::Value {
    // Compute per-second RPS
    let total = result.total_duration;
    if total <= 0.0 || result.request_results.is_empty() {
        return serde_json::json!({
            "mean": 0.0,
            "stddev": 0.0,
            "max": 0.0,
            "min": 0.0,
            "percentiles": {
                "p10": 0.0,
                "p25": 0.0,
                "p50": 0.0,
                "p75": 0.0,
                "p90": 0.0,
                "p95": 0.0,
                "p99": 0.0,
                "p99.9": 0.0,
                "p99.99": 0.0
            }
        });
    }

    // Build per-second buckets
    let n_seconds = total.ceil() as usize + 1;
    let mut per_second = vec![0.0f64; n_seconds.max(1)];

    for r in &result.request_results {
        if r.status.is_some() {
            let sec = r.start_time.floor() as usize;
            if sec < per_second.len() {
                per_second[sec] += 1.0;
            }
        }
    }

    // Filter non-zero seconds
    let rps_values: Vec<f64> = per_second.into_iter().filter(|&v| v > 0.0).collect();

    if rps_values.is_empty() {
        return serde_json::json!({
            "mean": 0.0,
            "stddev": 0.0,
            "max": 0.0,
            "min": 0.0,
            "percentiles": {}
        });
    }

    let mean = rps_values.iter().sum::<f64>() / rps_values.len() as f64;
    let variance = rps_values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / rps_values.len() as f64;
    let stddev = variance.sqrt();
    let max = rps_values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let min = rps_values.iter().cloned().fold(f64::INFINITY, f64::min);

    let mut sorted = rps_values.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    serde_json::json!({
        "mean": mean,
        "stddev": stddev,
        "max": max,
        "min": min,
        "percentiles": {
            "p10": percentile(&sorted, 10.0),
            "p25": percentile(&sorted, 25.0),
            "p50": percentile(&sorted, 50.0),
            "p75": percentile(&sorted, 75.0),
            "p90": percentile(&sorted, 90.0),
            "p95": percentile(&sorted, 95.0),
            "p99": percentile(&sorted, 99.0),
            "p99.9": percentile(&sorted, 99.9),
            "p99.99": percentile(&sorted, 99.99)
        }
    })
}

fn compute_dns_dialup(result: &LoadTestResult) -> (f64, f64, f64) {
    let values: Vec<f64> = result.request_results.iter()
        .filter(|r| r.status.is_some())
        .map(|r| r.dialup)
        .collect();

    if values.is_empty() {
        return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY);
    }

    let avg = values.iter().sum::<f64>() / values.len() as f64;
    let fast = values.iter().cloned().fold(f64::INFINITY, f64::min);
    let slow = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fast, slow)
}

fn compute_dns_lookup(result: &LoadTestResult) -> (f64, f64, f64) {
    let values: Vec<f64> = result.request_results.iter()
        .filter(|r| r.status.is_some())
        .map(|r| r.dns_lookup)
        .collect();

    if values.is_empty() {
        return (f64::NAN, f64::INFINITY, f64::NEG_INFINITY);
    }

    let avg = values.iter().sum::<f64>() / values.len() as f64;
    let fast = values.iter().cloned().fold(f64::INFINITY, f64::min);
    let slow = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    (avg, fast, slow)
}

pub fn format_csv(result: &LoadTestResult) -> String {
    let mut out = String::from("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");

    for r in &result.request_results {
        if let Some(status) = r.status {
            out += &format!("{},{},{},{},{},{},{}\n",
                r.start_time,
                r.dns_lookup,
                r.dialup,
                r.response_delay,
                r.duration,
                r.bytes,
                status
            );
        }
    }

    out
}
