fn determine_time_unit(args: &Args, durations: &[f64], total: f64) -> TimeUnitEnum {
    if let Some(ref unit) = args.time_unit {
        match unit {
            TimeUnit::Ns => return TimeUnitEnum::Ns,
            TimeUnit::Us => return TimeUnitEnum::Us,
            TimeUnit::Ms => return TimeUnitEnum::Ms,
            TimeUnit::S => return TimeUnitEnum::S,
            TimeUnit::M => return TimeUnitEnum::M,
            TimeUnit::H => return TimeUnitEnum::H,
        }
    }

    // Auto-determine based on average duration
    let avg = if durations.is_empty() {
        total
    } else {
        durations.iter().sum::<f64>() / durations.len() as f64
    };

    if avg.is_nan() || avg <= 0.0 {
        // Use total duration as reference
        let t = total;
        if t < 0.001 { TimeUnitEnum::Ns }
        else if t < 1.0 { TimeUnitEnum::Ms }
        else if t < 60.0 { TimeUnitEnum::S }
        else { TimeUnitEnum::M }
    } else if avg < 0.000001 { TimeUnitEnum::Ns }
    else if avg < 0.001 { TimeUnitEnum::Us }
    else if avg < 1.0 { TimeUnitEnum::Ms }
    else if avg < 60.0 { TimeUnitEnum::S }
    else { TimeUnitEnum::M }
}

#[derive(Clone)]
enum TimeUnitEnum {
    Ns, Us, Ms, S, M, H
}

fn get_time_unit_info(unit: &TimeUnitEnum) -> (&'static str, f64) {
    match unit {
        TimeUnitEnum::Ns => ("ns", 1e9),
        TimeUnitEnum::Us => ("us", 1e6),
        TimeUnitEnum::Ms => ("ms", 1e3),
        TimeUnitEnum::S => ("s", 1.0),
        TimeUnitEnum::M => ("m", 1.0 / 60.0),
        TimeUnitEnum::H => ("h", 1.0 / 3600.0),
    }
}

fn format_duration(secs: f64, unit: &TimeUnitEnum) -> String {
    if secs.is_nan() {
        let (name, _) = get_time_unit_info(unit);
        return format!("NaN {}", name);
    }
    if secs.is_infinite() {
        let (name, _) = get_time_unit_info(unit);
        if secs > 0.0 {
            return format!("inf {}", name);
        } else {
            return format!("-inf {}", name);
        }
    }

    let (name, multiplier) = get_time_unit_info(unit);
    let val = secs * multiplier;

    match unit {
        TimeUnitEnum::Ns => format!("{:.4} {}", val, name),
        _ => format!("{:.4} {}", val, name),
    }
}

fn format_bytes(bytes: usize) -> String {
    if bytes == 0 {
        return "0 B".to_string();
    }
    let f = bytes as f64;
    if f < 1024.0 {
        format!("{} B", bytes)
    } else if f < 1024.0 * 1024.0 {
        format!("{:.2} KiB", f / 1024.0)
    } else if f < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.2} MiB", f / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", f / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_bytes_f(bytes: f64) -> String {
    if bytes <= 0.0 {
        return "0 B".to_string();
    }
    if bytes < 1024.0 {
        format!("{:.0} B", bytes)
    } else if bytes < 1024.0 * 1024.0 {
        format!("{:.2} KiB", bytes / 1024.0)
    } else if bytes < 1024.0 * 1024.0 * 1024.0 {
        format!("{:.2} MiB", bytes / (1024.0 * 1024.0))
    } else {
        format!("{:.2} GiB", bytes / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_size_per_req(size: f64) -> String {
    if size.is_nan() {
        return "NaN".to_string();
    }
    if size < 1024.0 {
        format!("{:.0} B", size)
    } else if size < 1024.0 * 1024.0 {
        format!("{:.2} KiB", size / 1024.0)
    } else {
        format!("{:.2} MiB", size / (1024.0 * 1024.0))
    }
}

fn format_histogram(durations: &[f64], unit: &TimeUnitEnum, title: &str) -> String {
    let mut out = format!("{}\n", title);

    const NUM_BUCKETS: usize = 11;

    if durations.is_empty() {
        let nan_label = format_duration(f64::NAN, unit);
        for _ in 0..NUM_BUCKETS {
            out += &format!("  {:>10} [0] |\n", nan_label);
        }
        return out;
    }

    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let min = sorted[0];
    let max = sorted[sorted.len() - 1];

    let range = max - min;
    let bucket_size = if range == 0.0 { 1.0 } else { range / (NUM_BUCKETS as f64 - 1.0) };

    let mut buckets = vec![0usize; NUM_BUCKETS];
    let mut bucket_labels = vec![0.0f64; NUM_BUCKETS];

    for i in 0..NUM_BUCKETS {
        bucket_labels[i] = min + (i as f64) * bucket_size;
    }

    for &d in durations {
        if range == 0.0 {
            buckets[0] += 1;
        } else {
            let idx = ((d - min) / bucket_size).floor() as usize;
            let idx = idx.min(NUM_BUCKETS - 1);
            buckets[idx] += 1;
        }
    }

    let max_count = *buckets.iter().max().unwrap_or(&0);

    for i in 0..NUM_BUCKETS {
        let label = format_duration(bucket_labels[i], unit);
        let count = buckets[i];
        let bar = if max_count > 0 {
            let bar_len = (count as f64 / max_count as f64 * 32.0).round() as usize;
            "■".repeat(bar_len)
        } else {
            String::new()
        };
        out += &format!("  {:>10} [{}] |{}\n", label, count, bar);
    }

    out
}

fn format_distribution(durations: &[f64], unit: &TimeUnitEnum, title: &str) -> String {
    let mut out = format!("{}\n", title);

    let percentiles = [10.0, 25.0, 50.0, 75.0, 90.0, 95.0, 99.0, 99.9, 99.99];

    if durations.is_empty() {
        for &p in &percentiles {
            out += &format!("  {:.2}% in {}\n", p, format_duration(f64::NAN, unit));
        }
        return out;
    }

    let mut sorted = durations.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    for &p in &percentiles {
        let val = percentile(&sorted, p);
        out += &format!("  {:.2}% in {}\n", p, format_duration(val, unit));
    }

    out
}

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return f64::NAN;
    }
    let idx = (p / 100.0 * sorted.len() as f64).ceil() as usize;
    let idx = idx.min(sorted.len()) - 1;
    sorted[idx.max(0)]
}

pub fn format_json(result: &LoadTestResult) -> Result<String> {
