func newURLGenerator(cfg *Config) (*URLGenerator, error) {
	if cfg.RandRegexURL {
		r, err := randregex.New(cfg.URL, cfg.MaxRepeat)
		if err != nil {
			return nil, fmt.Errorf("invalid regex URL: %v", err)
		}
		return &URLGenerator{mode: 1, regex: r}, nil
	}
	if cfg.URLsFromFile {
		data, err := os.ReadFile(cfg.URL)
		if err != nil {
			return nil, fmt.Errorf("failed to read URLs file: %v", err)
		}
		var urls []string
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(line)
			if line != "" {
				urls = append(urls, line)
			}
		}
		if len(urls) == 0 {
			return nil, fmt.Errorf("no URLs found in file")
		}
		return &URLGenerator{mode: 2, urls: urls}, nil
	}
	return &URLGenerator{mode: 0, fixed: cfg.URL}, nil
}

func (g *URLGenerator) Generate() (string, error) {
	switch g.mode {
	case 0:
		return g.fixed, nil
	case 1:
		return g.regex.Generate()
	case 2:
		idx := globalRandIntn(len(g.urls))
		return g.urls[idx], nil
	}
	return g.fixed, nil
}

var globalRandMu sync.Mutex
var globalRandSeed int64 = time.Now().UnixNano()

func globalRandIntn(n int) int {
	globalRandMu.Lock()
	defer globalRandMu.Unlock()
	// Simple LCG
	globalRandSeed = globalRandSeed*6364136223846793005 + 1442695040888963407
	r := int((globalRandSeed>>33)&0x7fffffff) % n
	return r
}

// HTTP Client and load testing

func buildTransport(cfg *Config) (*http.Transport, error) {
	tlsCfg := &tls.Config{
		InsecureSkipVerify: cfg.Insecure,
	}

	if cfg.CACert != "" {
		certData, err := os.ReadFile(cfg.CACert)
		if err != nil {
			return nil, fmt.Errorf("reading CA cert: %v", err)
		}
		pool, err := x509.SystemCertPool()
		if err != nil {
			pool = x509.NewCertPool()
		}
		pool.AppendCertsFromPEM(certData)
		tlsCfg.RootCAs = pool
	}

	if cfg.Cert != "" && cfg.Key != "" {
		cert, err := tls.LoadX509KeyPair(cfg.Cert, cfg.Key)
		if err != nil {
			return nil, fmt.Errorf("loading client cert: %v", err)
		}
		tlsCfg.Certificates = []tls.Certificate{cert}
	}

	connectTimeout := 5 * time.Second
	if cfg.ConnectTimeout > 0 {
		connectTimeout = cfg.ConnectTimeout
	}

	dialer := &net.Dialer{
		Timeout: connectTimeout,
	}

	transport := &http.Transport{
		TLSClientConfig:     tlsCfg,
		DialContext:         dialer.DialContext,
		DisableKeepAlives:   cfg.DisableKeepA,
		DisableCompression:  cfg.DisableCompr,
		MaxIdleConnsPerHost: 1000,
		MaxConnsPerHost:     0,
	}

	if cfg.HTTP2 || cfg.HTTPVersion == "2" {
		// Force HTTP/2
		// Note: http2 support is built into Go's transport
	}

	return transport, nil
}

func buildClient(cfg *Config) (*http.Client, error) {
	transport, err := buildTransport(cfg)
	if err != nil {
		return nil, err
	}

	var redirectPolicy func(req *http.Request, via []*http.Request) error
	if cfg.Redirect == 0 {
		redirectPolicy = func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		}
	} else {
		maxRedirects := cfg.Redirect
		redirectPolicy = func(req *http.Request, via []*http.Request) error {
			if len(via) >= maxRedirects {
				return fmt.Errorf("stopped after %d redirects", maxRedirects)
			}
			return nil
		}
	}

	client := &http.Client{
		Transport:     transport,
		CheckRedirect: redirectPolicy,
	}

	if cfg.HasTimeout {
		client.Timeout = cfg.Timeout
	}

	return client, nil
}

func buildRequest(cfg *Config, urlStr string, bodyLinesCh <-chan []byte) (*http.Request, error) {
	method := cfg.Method
	if method == "" {
		method = "GET"
	}

	var body io.Reader
	var contentLength int64 = -1

	if cfg.BodyString != "" {
		body = strings.NewReader(cfg.BodyString)
		contentLength = int64(len(cfg.BodyString))
	} else if cfg.BodyPath != "" {
		data, err := os.ReadFile(cfg.BodyPath)
		if err != nil {
			return nil, fmt.Errorf("reading body file: %v", err)
		}
		body = strings.NewReader(string(data))
		contentLength = int64(len(data))
	} else if cfg.BodyPathLines != "" && bodyLinesCh != nil {
		select {
		case line := <-bodyLinesCh:
			body = strings.NewReader(string(line))
			contentLength = int64(len(line))
		default:
		}
	} else if len(cfg.Form) > 0 {
		// Multipart form
		var buf strings.Builder
		w := multipart.NewWriter(&buf)
		for _, f := range cfg.Form {
			if strings.HasPrefix(f, "@") {
				// File field
				parts := strings.SplitN(f[1:], "=", 2)
				if len(parts) == 2 {
					data, err := os.ReadFile(parts[1])
					if err == nil {
						fw, _ := w.CreateFormFile(parts[0], filepath.Base(parts[1]))
						fw.Write(data)
					}
				}
			} else {
				parts := strings.SplitN(f, "=", 2)
				if len(parts) == 2 {
					w.WriteField(parts[0], parts[1])
				}
			}
		}
		w.Close()
		body = strings.NewReader(buf.String())
	}

	req, err := http.NewRequest(method, urlStr, body)
	if err != nil {
		return nil, err
	}

	if contentLength >= 0 {
		req.ContentLength = contentLength
	}

	// Default headers
	req.Header.Set("Accept", "*/*")
	if !cfg.DisableCompr {
		req.Header.Set("Accept-Encoding", "gzip, compress, deflate, br")
	}
	req.Header.Set("User-Agent", "oha/"+Version)

	// Custom headers
	for _, h := range cfg.Headers {
		if pos := strings.Index(h, ":"); pos > 0 {
			key := strings.TrimSpace(h[:pos])
			val := strings.TrimSpace(h[pos+1:])
			req.Header.Set(key, val)
		}
	}

	// Accept header
	if cfg.AcceptHeader != "" {
		req.Header.Set("Accept", cfg.AcceptHeader)
	}

	// Content-Type
	if cfg.ContentType != "" {
		req.Header.Set("Content-Type", cfg.ContentType)
	} else if len(cfg.Form) > 0 {
		// Set multipart content type
	}

	// Host header
	if cfg.Host != "" {
		req.Host = cfg.Host
	}

	// Basic auth
	if cfg.BasicAuth != "" {
		if pos := strings.Index(cfg.BasicAuth, ":"); pos >= 0 {
			user := cfg.BasicAuth[:pos]
			pass := cfg.BasicAuth[pos+1:]
			encoded := base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
			req.Header.Set("Authorization", "Basic "+encoded)
		}
	}

	return req, nil
}

func doRequest(client *http.Client, cfg *Config, urlStr string, bodyLinesCh <-chan []byte, testStart time.Time) RequestResult {
	req, err := buildRequest(cfg, urlStr, bodyLinesCh)
	if err != nil {
		return RequestResult{
			StartTime: time.Since(testStart).Seconds(),
			Error:     err.Error(),
		}
	}

	var dnsStart, dnsDone, connectDone time.Time
	var ttfb time.Time
	var reqStart time.Time

	trace := &httptrace.ClientTrace{
		DNSStart: func(info httptrace.DNSStartInfo) {
			dnsStart = time.Now()
		},
		DNSDone: func(info httptrace.DNSDoneInfo) {
			dnsDone = time.Now()
		},
		ConnectDone: func(network, addr string, err error) {
			connectDone = time.Now()
		},
		GotFirstResponseByte: func() {
			ttfb = time.Now()
		},
	}

	req = req.WithContext(httptrace.WithClientTrace(req.Context(), trace))

	startOffset := time.Since(testStart).Seconds()
	reqStart = time.Now()
	dnsStart = reqStart

	resp, err := client.Do(req)
	if err != nil {
		return RequestResult{
			StartTime: startOffset,
			Error:     simplifyError(err.Error()),
		}
	}
	defer resp.Body.Close()

	bodyBytes, readErr := io.ReadAll(resp.Body)
	endTime := time.Now()

	if readErr != nil {
		return RequestResult{
			StartTime: startOffset,
			Error:     simplifyError(readErr.Error()),
		}
	}

	dnsLookup := 0.0
	if !dnsDone.IsZero() && !dnsStart.IsZero() {
		dnsLookup = dnsDone.Sub(dnsStart).Seconds()
	}

	dialup := 0.0
	if !connectDone.IsZero() {
		dialup = connectDone.Sub(reqStart).Seconds()
	} else if !dnsDone.IsZero() {
		dialup = dnsDone.Sub(reqStart).Seconds()
	}

	responseDelay := 0.0
	if !ttfb.IsZero() && !connectDone.IsZero() {
		responseDelay = ttfb.Sub(connectDone).Seconds()
	} else if !ttfb.IsZero() {
		responseDelay = ttfb.Sub(reqStart).Seconds()
	}

	duration := endTime.Sub(reqStart).Seconds()

	return RequestResult{
		StartTime:     startOffset,
		DNSLookup:     dnsLookup,
		DNSDialup:     dialup,
		ResponseDelay: responseDelay,
		Duration:      duration,
		Bytes:         int64(len(bodyBytes)),
		Status:        resp.StatusCode,
		HasStatus:     true,
	}
}

func simplifyError(msg string) string {
	// Simplify common error messages to match oha's output
	if strings.Contains(msg, "connection refused") {
		return "Connection refused (os error 111)"
	}
	if strings.Contains(msg, "EOF") || strings.Contains(msg, "connection reset") {
		return "connection closed before message completed"
	}
	if strings.Contains(msg, "timeout") || strings.Contains(msg, "Timeout") {
		return "timeout"
	}
	// Strip the URL from error messages
	re := regexp.MustCompile(`(?:Get|Post|Put|Delete|Patch|Head) ".*?": (.+)`)
	if m := re.FindStringSubmatch(msg); len(m) > 1 {
		return m[1]
	}
	return msg
}

func runLoadTest(cfg *Config) (*LoadTestResult, error) {
	client, err := buildClient(cfg)
	if err != nil {
		return nil, err
	}

	urlGen, err := newURLGenerator(cfg)
	if err != nil {
		return nil, err
	}

	// Pre-lookup DNS
	if !cfg.NoPreLookup && !cfg.RandRegexURL && !cfg.URLsFromFile {
		parsedURL, err := url.Parse(cfg.URL)
		if err == nil {
			host := parsedURL.Hostname()
			if host != "" {
				net.LookupHost(host) // ignore error, just warm up DNS
			}
		}
	}

	var results []RequestResult
	var mu sync.Mutex

	testStart := time.Now()

	nWorkers := cfg.NConnections
	if nWorkers <= 0 {
		nWorkers = 50
	}

	if cfg.HasDuration {
		// Duration-based test
		deadline := testStart.Add(cfg.Duration)
		var wg sync.WaitGroup

		for i := 0; i < nWorkers; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for {
					if time.Now().After(deadline) {
						break
					}
					u, err := urlGen.Generate()
					if err != nil {
						break
					}
					r := doRequest(client, cfg, u, nil, testStart)
					mu.Lock()
					results = append(results, r)
					mu.Unlock()
				}
			}()
		}
		wg.Wait()
	} else if cfg.HasQPS {
		// QPS-based test
		nReq := cfg.NRequests
		interval := time.Duration(float64(time.Second) / cfg.QPS)

		var completed int64
		var wg sync.WaitGroup

		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		sem := make(chan struct{}, nWorkers)

		for range ticker.C {
			cur := atomic.AddInt64(&completed, 1)
			if int(cur) > nReq {
				break
			}

			u, err := urlGen.Generate()
			if err != nil {
				break
			}
			sem <- struct{}{}
			wg.Add(1)
			go func(urlStr string) {
				defer wg.Done()
				defer func() { <-sem }()
				r := doRequest(client, cfg, urlStr, nil, testStart)
				mu.Lock()
				results = append(results, r)
				mu.Unlock()
			}(u)
		}
		wg.Wait()
	} else {
		// Request count based test
		nReq := cfg.NRequests
		var counter int64

		var wg sync.WaitGroup
		for i := 0; i < nWorkers; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for {
					cur := atomic.AddInt64(&counter, 1)
					if int(cur) > nReq {
						return
					}
					u, err := urlGen.Generate()
					if err != nil {
						return
					}
					r := doRequest(client, cfg, u, nil, testStart)
					mu.Lock()
					results = append(results, r)
					mu.Unlock()
				}
			}()
		}
		wg.Wait()
	}

	totalDuration := time.Since(testStart).Seconds()

	return &LoadTestResult{
		TotalDuration: totalDuration,
		Results:       results,
	}, nil
}

// Statistics helpers

func successResults(results []RequestResult) []RequestResult {
	var r []RequestResult
	for _, res := range results {
		if res.HasStatus {
			r = append(r, res)
		}
	}
	return r
}

func getdurations(results []RequestResult) []float64 {
	var d []float64
	for _, r := range results {
		if r.HasStatus {
			d = append(d, r.Duration)
		}
	}
	return d
}

func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return math.NaN()
	}
	idx := int(math.Ceil(p/100.0*float64(len(sorted)))) - 1
	if idx < 0 {
		idx = 0
	}
	if idx >= len(sorted) {
		idx = len(sorted) - 1
	}
	return sorted[idx]
}

func computeStats(durations []float64) (min, max, avg float64) {
	if len(durations) == 0 {
		return math.Inf(1), math.Inf(-1), math.NaN()
	}
	min = math.Inf(1)
	max = math.Inf(-1)
	sum := 0.0
	for _, d := range durations {
		if d < min {
			min = d
		}
		if d > max {
			max = d
		}
		sum += d
	}
	avg = sum / float64(len(durations))
	return
}

// Time unit formatting

func autoTimeUnit(avgSeconds float64) TimeUnit {
	if math.IsNaN(avgSeconds) || avgSeconds <= 0 {
		return TimeUnitMs
	}
	if avgSeconds < 1e-6 {
		return TimeUnitNs
	}
	if avgSeconds < 1e-3 {
		return TimeUnitUs
	}
	if avgSeconds < 1.0 {
		return TimeUnitMs
	}
	if avgSeconds < 60.0 {
		return TimeUnitS
	}
	return TimeUnitM
}

type unitInfo struct {
	name       string
	multiplier float64
}

func getUnitInfo(u TimeUnit) unitInfo {
	switch u {
	case TimeUnitNs:
		return unitInfo{"ns", 1e9}
	case TimeUnitUs:
		return unitInfo{"us", 1e6}
	case TimeUnitMs:
		return unitInfo{"ms", 1e3}
	case TimeUnitS:
		return unitInfo{"sec", 1.0}
	case TimeUnitM:
		return unitInfo{"min", 1.0 / 60.0}
	case TimeUnitH:
		return unitInfo{"hr", 1.0 / 3600.0}
	default:
		return unitInfo{"ms", 1e3}
	}
}

func formatDuration(secs float64, u unitInfo) string {
	if math.IsNaN(secs) {
		return fmt.Sprintf("NaN %s", u.name)
	}
	if math.IsInf(secs, 1) {
		return fmt.Sprintf("inf %s", u.name)
	}
	if math.IsInf(secs, -1) {
		return fmt.Sprintf("-inf %s", u.name)
	}
	val := secs * u.multiplier
	return fmt.Sprintf("%.4f %s", val, u.name)
}

func formatDurationHist(secs float64, u unitInfo) string {
	if math.IsNaN(secs) {
		return fmt.Sprintf("NaN %s", u.name)
	}
	val := secs * u.multiplier
	return fmt.Sprintf("%.3f %s", val, u.name)
}

func formatBytes(n int64) string {
	if n == 0 {
		return "0 B"
	}
	f := float64(n)
	if f < 1024 {
		return fmt.Sprintf("%d B", n)
	} else if f < 1024*1024 {
		return fmt.Sprintf("%.2f KiB", f/1024)
	} else if f < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MiB", f/(1024*1024))
	}
	return fmt.Sprintf("%.2f GiB", f/(1024*1024*1024))
}

func formatBytesF(f float64) string {
	if f <= 0 {
		return "0 B"
	}
	if f < 1024 {
		return fmt.Sprintf("%.0f B", f)
	} else if f < 1024*1024 {
		return fmt.Sprintf("%.2f KiB", f/1024)
	} else if f < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MiB", f/(1024*1024))
	}
	return fmt.Sprintf("%.2f GiB", f/(1024*1024*1024))
}

func formatSizePerReq(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if f < 1024 {
		return fmt.Sprintf("%.0f B", f)
	} else if f < 1024*1024 {
		return fmt.Sprintf("%.2f KiB", f/1024)
	}
	return fmt.Sprintf("%.2f MiB", f/(1024*1024))
}

// Histogram computation

type histBucket struct {
	label string
	count int
}

func computeHistogram(durations []float64, u unitInfo) []histBucket {
	const numBuckets = 11

	if len(durations) == 0 {
		buckets := make([]histBucket, numBuckets)
		for i := range buckets {
			buckets[i] = histBucket{fmt.Sprintf("NaN %s", u.name), 0}
		}
		return buckets
	}

	sorted := make([]float64, len(durations))
	copy(sorted, durations)
	sort.Float64s(sorted)

	minV := sorted[0]
	maxV := sorted[len(sorted)-1]
	rangeV := maxV - minV

	var bucketSize float64
	if rangeV == 0 {
		bucketSize = 0
	} else {
		bucketSize = rangeV / float64(numBuckets-1)
	}

	counts := make([]int, numBuckets)
	labels := make([]float64, numBuckets)
	for i := 0; i < numBuckets; i++ {
		labels[i] = minV + float64(i)*bucketSize
	}

	for _, d := range durations {
		var idx int
		if rangeV == 0 {
			idx = 0
		} else {
			idx = int(math.Floor((d - minV) / bucketSize))
			if idx >= numBuckets {
				idx = numBuckets - 1
			}
			if idx < 0 {
				idx = 0
			}
		}
		counts[idx]++
	}

	buckets := make([]histBucket, numBuckets)
	for i, label := range labels {
		buckets[i] = histBucket{
			label: formatDurationHist(label, u),
			count: counts[i],
		}
	}
	return buckets
}

func renderHistogram(buckets []histBucket, title string) string {
	var sb strings.Builder
	sb.WriteString(title)
	sb.WriteString("\n")

	// Find max count
	maxCount := 0
	for _, b := range buckets {
		if b.count > maxCount {
			maxCount = b.count
		}
	}

	// Find max label width
	maxLabelWidth := 0
	for _, b := range buckets {
		w := utf8.RuneCountInString(b.label)
		if w > maxLabelWidth {
			maxLabelWidth = w
		}
	}

	// Find max count digits
	maxCountDigits := len(strconv.Itoa(maxCount))

	const maxBars = 32

	for _, b := range buckets {
		labelWidth := utf8.RuneCountInString(b.label)
		padding := maxLabelWidth - labelWidth
		paddingStr := strings.Repeat(" ", padding)

		countStr := strconv.Itoa(b.count)
		countPadding := strings.Repeat(" ", maxCountDigits-len(countStr))

		var bars string
		if maxCount > 0 {
			numBars := int(math.Round(float64(b.count) / float64(maxCount) * maxBars))
			bars = strings.Repeat("■", numBars)
		}

		sb.WriteString(fmt.Sprintf("  %s%s [%s%s] |%s\n",
			paddingStr, b.label, countStr, countPadding, bars))
	}

	return sb.String()
}

func renderDistribution(sorted []float64, u unitInfo, title string) string {
	var sb strings.Builder
	sb.WriteString(title)
	sb.WriteString("\n")

	ps := []float64{10, 25, 50, 75, 90, 95, 99, 99.9, 99.99}
	for _, p := range ps {
		v := percentile(sorted, p)
		sb.WriteString(fmt.Sprintf("  %.2f%% in %s\n", p, formatDuration(v, u)))
	}
	return sb.String()
}

// Output formatters

func formatText(result *LoadTestResult, cfg *Config) string {
	var sb strings.Builder

	durations := getdurations(result.Results)
	total := result.TotalDuration
	sr := result.Results

	// Count successful (all with status)
	successCount := 0
	totalBytes := int64(0)
	for _, r := range sr {
		if r.HasStatus {
			successCount++
			totalBytes += r.Bytes
		}
	}

	successRate := 0.0
	if len(sr) > 0 {
		successRate = float64(successCount) / float64(len(sr))
	}

	minD, maxD, avgD := computeStats(durations)

	requestsPerSec := float64(len(sr)) / total

	var sizePerReq float64
	if successCount > 0 {
		sizePerReq = float64(totalBytes) / float64(successCount)
	} else {
		sizePerReq = math.NaN()
	}
	sizePerSec := float64(totalBytes) / total

	// Determine time unit
	var u unitInfo
	if cfg.TimeUnit == TimeUnitAuto {
		u = getUnitInfo(autoTimeUnit(avgD))
	} else {
		u = getUnitInfo(cfg.TimeUnit)
	}

	sb.WriteString("Summary:\n")
	sb.WriteString(fmt.Sprintf("  Success rate:\t%.2f%%\n", successRate*100))
	sb.WriteString(fmt.Sprintf("  Total:\t%s\n", formatDuration(total, u)))
	sb.WriteString(fmt.Sprintf("  Slowest:\t%s\n", formatDuration(maxD, u)))
	sb.WriteString(fmt.Sprintf("  Fastest:\t%s\n", formatDuration(minD, u)))
	sb.WriteString(fmt.Sprintf("  Average:\t%s\n", formatDuration(avgD, u)))
	sb.WriteString(fmt.Sprintf("  Requests/sec:\t%.4f\n", requestsPerSec))
	sb.WriteString("\n")
	sb.WriteString(fmt.Sprintf("  Total data:\t%s\n", formatBytes(totalBytes)))
	sb.WriteString(fmt.Sprintf("  Size/request:\t%s\n", formatSizePerReq(sizePerReq)))
	sb.WriteString(fmt.Sprintf("  Size/sec:\t%s\n", formatBytesF(sizePerSec)))
	sb.WriteString("\n")

	// Histogram
	buckets := computeHistogram(durations, u)
	sb.WriteString(renderHistogram(buckets, "Response time histogram:"))
	sb.WriteString("\n")

	// Distribution
	sortedD := make([]float64, len(durations))
	copy(sortedD, durations)
	sort.Float64s(sortedD)
	sb.WriteString(renderDistribution(sortedD, u, "Response time distribution:"))
	sb.WriteString("\n")

	// Stats breakdown
	if cfg.StatsBreakdown {
		var twoxxD []float64
		var fourFivexxD []float64
		for _, r := range sr {
			if r.HasStatus {
				if r.Status >= 200 && r.Status < 300 {
					twoxxD = append(twoxxD, r.Duration)
				} else if r.Status >= 400 {
					fourFivexxD = append(fourFivexxD, r.Duration)
				}
			}
		}

		buckets2xx := computeHistogram(twoxxD, u)
		sb.WriteString(renderHistogram(buckets2xx, "Response time histogram (2xx only):"))
		sb.WriteString("\n")

		sorted2xx := make([]float64, len(twoxxD))
		copy(sorted2xx, twoxxD)
		sort.Float64s(sorted2xx)
		sb.WriteString(renderDistribution(sorted2xx, u, "Response time distribution (2xx only):"))
		sb.WriteString("\n")

		bucketsErr := computeHistogram(fourFivexxD, u)
		sb.WriteString(renderHistogram(bucketsErr, "Response time histogram (4xx + 5xx only):"))
		sb.WriteString("\n")

		sortedErr := make([]float64, len(fourFivexxD))
		copy(sortedErr, fourFivexxD)
		sort.Float64s(sortedErr)
		sb.WriteString(renderDistribution(sortedErr, u, "Response time distribution (4xx + 5xx only):"))
		sb.WriteString("\n")

		sb.WriteString("\n")
	}

	// DNS details
	var dialupTimes, lookupTimes []float64
	for _, r := range sr {
		if r.HasStatus {
			dialupTimes = append(dialupTimes, r.DNSDialup)
			lookupTimes = append(lookupTimes, r.DNSLookup)
		}
	}

	dialupMin, dialupMax, dialupAvg := computeStats(dialupTimes)
	lookupMin, lookupMax, lookupAvg := computeStats(lookupTimes)

	sb.WriteString("Details (average, fastest, slowest):\n")
	sb.WriteString(fmt.Sprintf("  DNS+dialup:\t%s, %s, %s\n",
		formatDuration(dialupAvg, u),
		formatDuration(dialupMin, u),
		formatDuration(dialupMax, u)))
	sb.WriteString(fmt.Sprintf("  DNS-lookup:\t%s, %s, %s\n",
		formatDuration(lookupAvg, u),
		formatDuration(lookupMin, u),
		formatDuration(lookupMax, u)))
	sb.WriteString("\n")

	// Status code distribution
	statusDist := make(map[int]int)
	for _, r := range sr {
		if r.HasStatus {
			statusDist[r.Status]++
		}
	}

	var statuses []int
	for s := range statusDist {
		statuses = append(statuses, s)
	}
	sort.Ints(statuses)

	sb.WriteString("Status code distribution:\n")
	for _, s := range statuses {
		count := statusDist[s]
		word := "responses"
		if count == 1 {
			word = "response"
		}
		sb.WriteString(fmt.Sprintf("  [%d] %d %s\n", s, count, word))
	}

	// Error distribution
	errDist := make(map[string]int)
	for _, r := range sr {
		if !r.HasStatus && r.Error != "" {
			errDist[r.Error]++
		}
	}

	if len(errDist) > 0 {
		sb.WriteString("\nError distribution:\n")
		var errs []string
		for e := range errDist {
			errs = append(errs, e)
		}
		sort.Strings(errs)
		for _, e := range errs {
			sb.WriteString(fmt.Sprintf("  [%d] %s\n", errDist[e], e))
		}
	}

	return sb.String()
}

func formatJSON(result *LoadTestResult) (string, error) {
	durations := getdurations(result.Results)
	total := result.TotalDuration

	successCount := 0
	totalBytes := int64(0)
	for _, r := range result.Results {
		if r.HasStatus {
			successCount++
			totalBytes += r.Bytes
		}
	}

	successRate := 0.0
	if len(result.Results) > 0 {
		successRate = float64(successCount) / float64(len(result.Results))
	}

	minD, maxD, avgD := computeStats(durations)
	requestsPerSec := float64(len(result.Results)) / total

	var sizePerReq float64
	if successCount > 0 {
		sizePerReq = float64(totalBytes) / float64(successCount)
	}
	sizePerSec := float64(totalBytes) / total

	// Build histogram map
	const numBuckets = 11
	histMap := make(map[string]int)
	if len(durations) > 0 {
		sorted := make([]float64, len(durations))
		copy(sorted, durations)
		sort.Float64s(sorted)
		minV := sorted[0]
		maxV := sorted[len(sorted)-1]
		rangeV := maxV - minV
		var bucketSize float64
		if rangeV != 0 {
			bucketSize = rangeV / float64(numBuckets-1)
		}

		labels := make([]float64, numBuckets)
		counts := make([]int, numBuckets)
		for i := 0; i < numBuckets; i++ {
			labels[i] = minV + float64(i)*bucketSize
		}

		for _, d := range durations {
			var idx int
			if rangeV == 0 {
				idx = 0
			} else {
				idx = int(math.Floor((d - minV) / bucketSize))
				if idx >= numBuckets {
					idx = numBuckets - 1
				}
				if idx < 0 {
					idx = 0
				}
			}
			counts[idx]++
		}

		for i, label := range labels {
			histMap[strconv.FormatFloat(label, 'f', -1, 64)] = counts[i]
		}
	}

	// Percentiles
	sortedD := make([]float64, len(durations))
	copy(sortedD, durations)
	sort.Float64s(sortedD)

	p10 := percentile(sortedD, 10)
	p25 := percentile(sortedD, 25)
	p50 := percentile(sortedD, 50)
	p75 := percentile(sortedD, 75)
	p90 := percentile(sortedD, 90)
	p95 := percentile(sortedD, 95)
	p99 := percentile(sortedD, 99)
	p999 := percentile(sortedD, 99.9)
	p9999 := percentile(sortedD, 99.99)

	// RPS stats
	rpsStats := computeRPSStats(result)

	// DNS details
	var dialupTimes, lookupTimes []float64
	for _, r := range result.Results {
		if r.HasStatus {
			dialupTimes = append(dialupTimes, r.DNSDialup)
			lookupTimes = append(lookupTimes, r.DNSLookup)
		}
	}
	diaMin, diaMax, diaAvg := computeStats(dialupTimes)
	lookMin, lookMax, lookAvg := computeStats(lookupTimes)

	// Status distribution
	statusDist := make(map[string]int)
	for _, r := range result.Results {
		if r.HasStatus {
			statusDist[strconv.Itoa(r.Status)]++
		}
	}

	// Error distribution
	errDist := make(map[string]int)
	for _, r := range result.Results {
		if !r.HasStatus && r.Error != "" {
			errDist[r.Error]++
		}
	}

	output := map[string]interface{}{
		"summary": map[string]interface{}{
			"successRate":    successRate,
			"total":          total,
			"slowest":        maxD,
			"fastest":        minD,
			"average":        avgD,
			"requestsPerSec": requestsPerSec,
			"totalData":      int(totalBytes),
			"sizePerRequest": int(sizePerReq),
			"sizePerSec":     sizePerSec,
		},
		"responseTimeHistogram": histMap,
		"latencyPercentiles": map[string]interface{}{
			"p10":   p10,
			"p25":   p25,
			"p50":   p50,
			"p75":   p75,
			"p90":   p90,
			"p95":   p95,
			"p99":   p99,
			"p99.9": p999,
			"p99.99": p9999,
		},
		"rps": rpsStats,
		"details": map[string]interface{}{
			"DNSDialup": map[string]interface{}{
				"average": diaAvg,
				"fastest": diaMin,
				"slowest": diaMax,
			},
			"DNSLookup": map[string]interface{}{
				"average": lookAvg,
				"fastest": lookMin,
				"slowest": lookMax,
			},
		},
		"statusCodeDistribution": statusDist,
		"errorDistribution":      errDist,
	}

	data, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func computeRPSStats(result *LoadTestResult) map[string]interface{} {
	total := result.TotalDuration
	if total <= 0 || len(result.Results) == 0 {
		return map[string]interface{}{
			"mean": 0.0, "stddev": 0.0, "max": 0.0, "min": 0.0,
			"percentiles": map[string]interface{}{},
		}
	}

	nSeconds := int(math.Ceil(total)) + 1
	if nSeconds < 1 {
		nSeconds = 1
	}
	perSecond := make([]float64, nSeconds)

	for _, r := range result.Results {
		if r.HasStatus {
			sec := int(math.Floor(r.StartTime))
			if sec < len(perSecond) {
				perSecond[sec]++
			}
		}
	}

	var rpsVals []float64
	for _, v := range perSecond {
		if v > 0 {
			rpsVals = append(rpsVals, v)
		}
	}

	if len(rpsVals) == 0 {
		return map[string]interface{}{
			"mean": 0.0, "stddev": 0.0, "max": 0.0, "min": 0.0,
			"percentiles": map[string]interface{}{},
		}
	}

	mean := 0.0
	for _, v := range rpsVals {
		mean += v
	}
	mean /= float64(len(rpsVals))

	variance := 0.0
	for _, v := range rpsVals {
		variance += (v - mean) * (v - mean)
	}
	variance /= float64(len(rpsVals))
	stddev := math.Sqrt(variance)

	maxRPS := rpsVals[0]
	minRPS := rpsVals[0]
	for _, v := range rpsVals {
		if v > maxRPS {
			maxRPS = v
		}
		if v < minRPS {
			minRPS = v
		}
	}

	sort.Float64s(rpsVals)

	return map[string]interface{}{
		"mean":   mean,
		"stddev": stddev,
		"max":    maxRPS,
		"min":    minRPS,
		"percentiles": map[string]interface{}{
			"p10":   percentile(rpsVals, 10),
			"p25":   percentile(rpsVals, 25),
			"p50":   percentile(rpsVals, 50),
			"p75":   percentile(rpsVals, 75),
			"p90":   percentile(rpsVals, 90),
			"p95":   percentile(rpsVals, 95),
			"p99":   percentile(rpsVals, 99),
			"p99.9": percentile(rpsVals, 99.9),
			"p99.99": percentile(rpsVals, 99.99),
		},
	}
}

func formatCSV(result *LoadTestResult) string {
	var buf strings.Builder
	w := csv.NewWriter(&buf)
	w.Write([]string{"request-start", "DNS", "DNS+dialup", "Response-delay", "request-duration", "bytes", "status"})
	for _, r := range result.Results {
		if r.HasStatus {
			w.Write([]string{
				strconv.FormatFloat(r.StartTime, 'f', -1, 64),
				strconv.FormatFloat(r.DNSLookup, 'f', -1, 64),
				strconv.FormatFloat(r.DNSDialup, 'f', -1, 64),
				strconv.FormatFloat(r.ResponseDelay, 'f', -1, 64),
				strconv.FormatFloat(r.Duration, 'f', -1, 64),
				strconv.FormatInt(r.Bytes, 10),
				strconv.Itoa(r.Status),
			})
		}
	}
	w.Flush()
	return buf.String()
}

