func formatText(result *LoadTestResult, cfg *Config) string {
	var sb strings.Builder

	durations := getdurations(result.Results)
	total := result.TotalDuration
	sr := result.Results

	// Count successful (all with status)
	successCount := 0
	totalBytes := int64(0)
	for _, r := range sr {
		if r.HasStatus {
			successCount++
			totalBytes += r.Bytes
		}
	}

	successRate := 0.0
	if len(sr) > 0 {
		successRate = float64(successCount) / float64(len(sr))
	}

	minD, maxD, avgD := computeStats(durations)

	requestsPerSec := float64(len(sr)) / total

	var sizePerReq float64
	if successCount > 0 {
		sizePerReq = float64(totalBytes) / float64(successCount)
	} else {
		sizePerReq = math.NaN()
	}
	sizePerSec := float64(totalBytes) / total

	// Determine time unit
	var u unitInfo
	if cfg.TimeUnit == TimeUnitAuto {
		u = getUnitInfo(autoTimeUnit(avgD))
	} else {
		u = getUnitInfo(cfg.TimeUnit)
	}

	sb.WriteString("Summary:\n")
	sb.WriteString(fmt.Sprintf("  Success rate:\t%.2f%%\n", successRate*100))
	sb.WriteString(fmt.Sprintf("  Total:\t%s\n", formatDuration(total, u)))
	sb.WriteString(fmt.Sprintf("  Slowest:\t%s\n", formatDuration(maxD, u)))
	sb.WriteString(fmt.Sprintf("  Fastest:\t%s\n", formatDuration(minD, u)))
	sb.WriteString(fmt.Sprintf("  Average:\t%s\n", formatDuration(avgD, u)))
	sb.WriteString(fmt.Sprintf("  Requests/sec:\t%.4f\n", requestsPerSec))
	sb.WriteString("\n")
	sb.WriteString(fmt.Sprintf("  Total data:\t%s\n", formatBytes(totalBytes)))
	sb.WriteString(fmt.Sprintf("  Size/request:\t%s\n", formatSizePerReq(sizePerReq)))
	sb.WriteString(fmt.Sprintf("  Size/sec:\t%s\n", formatBytesF(sizePerSec)))
	sb.WriteString("\n")

	// Histogram
	buckets := computeHistogram(durations, u)
	sb.WriteString(renderHistogram(buckets, "Response time histogram:"))
	sb.WriteString("\n")

	// Distribution
	sortedD := make([]float64, len(durations))
	copy(sortedD, durations)
	sort.Float64s(sortedD)
	sb.WriteString(renderDistribution(sortedD, u, "Response time distribution:"))
	sb.WriteString("\n")

	// Stats breakdown
	if cfg.StatsBreakdown {
		var twoxxD []float64
		var fourFivexxD []float64
		for _, r := range sr {
			if r.HasStatus {
				if r.Status >= 200 && r.Status < 300 {
					twoxxD = append(twoxxD, r.Duration)
				} else if r.Status >= 400 {
					fourFivexxD = append(fourFivexxD, r.Duration)
				}
			}
		}

		buckets2xx := computeHistogram(twoxxD, u)
		sb.WriteString(renderHistogram(buckets2xx, "Response time histogram (2xx only):"))
		sb.WriteString("\n")

		sorted2xx := make([]float64, len(twoxxD))
		copy(sorted2xx, twoxxD)
		sort.Float64s(sorted2xx)
		sb.WriteString(renderDistribution(sorted2xx, u, "Response time distribution (2xx only):"))
		sb.WriteString("\n")

		bucketsErr := computeHistogram(fourFivexxD, u)
		sb.WriteString(renderHistogram(bucketsErr, "Response time histogram (4xx + 5xx only):"))
		sb.WriteString("\n")

		sortedErr := make([]float64, len(fourFivexxD))
		copy(sortedErr, fourFivexxD)
		sort.Float64s(sortedErr)
		sb.WriteString(renderDistribution(sortedErr, u, "Response time distribution (4xx + 5xx only):"))
		sb.WriteString("\n")

		sb.WriteString("\n")
	}

	// DNS details
	var dialupTimes, lookupTimes []float64
	for _, r := range sr {
		if r.HasStatus {
			dialupTimes = append(dialupTimes, r.DNSDialup)
			lookupTimes = append(lookupTimes, r.DNSLookup)
		}
	}

	dialupMin, dialupMax, dialupAvg := computeStats(dialupTimes)
	lookupMin, lookupMax, lookupAvg := computeStats(lookupTimes)

	sb.WriteString("Details (average, fastest, slowest):\n")
	sb.WriteString(fmt.Sprintf("  DNS+dialup:\t%s, %s, %s\n",
		formatDuration(dialupAvg, u),
		formatDuration(dialupMin, u),
		formatDuration(dialupMax, u)))
	sb.WriteString(fmt.Sprintf("  DNS-lookup:\t%s, %s, %s\n",
		formatDuration(lookupAvg, u),
		formatDuration(lookupMin, u),
		formatDuration(lookupMax, u)))
	sb.WriteString("\n")

	// Status code distribution
	statusDist := make(map[int]int)
	for _, r := range sr {
		if r.HasStatus {
			statusDist[r.Status]++
		}
	}

	var statuses []int
	for s := range statusDist {
		statuses = append(statuses, s)
	}
	sort.Ints(statuses)

	sb.WriteString("Status code distribution:\n")
	for _, s := range statuses {
		count := statusDist[s]
		word := "responses"
		if count == 1 {
			word = "response"
		}
		sb.WriteString(fmt.Sprintf("  [%d] %d %s\n", s, count, word))
	}

	// Error distribution
	errDist := make(map[string]int)
	for _, r := range sr {
		if !r.HasStatus && r.Error != "" {
			errDist[r.Error]++
		}
	}

	if len(errDist) > 0 {
		sb.WriteString("\nError distribution:\n")
		var errs []string
		for e := range errDist {
			errs = append(errs, e)
		}
		sort.Strings(errs)
		for _, e := range errs {
			sb.WriteString(fmt.Sprintf("  [%d] %s\n", errDist[e], e))
		}
	}

	return sb.String()
}

func formatJSON(result *LoadTestResult) (string, error) {
	durations := getdurations(result.Results)
	total := result.TotalDuration

	successCount := 0
	totalBytes := int64(0)
	for _, r := range result.Results {
		if r.HasStatus {
			successCount++
			totalBytes += r.Bytes
		}
	}

	successRate := 0.0
	if len(result.Results) > 0 {
		successRate = float64(successCount) / float64(len(result.Results))
	}

	minD, maxD, avgD := computeStats(durations)
	requestsPerSec := float64(len(result.Results)) / total

	var sizePerReq float64
	if successCount > 0 {
		sizePerReq = float64(totalBytes) / float64(successCount)
	}
	sizePerSec := float64(totalBytes) / total

	// Build histogram map
	const numBuckets = 11
	histMap := make(map[string]int)
	if len(durations) > 0 {
		sorted := make([]float64, len(durations))
		copy(sorted, durations)
		sort.Float64s(sorted)
		minV := sorted[0]
		maxV := sorted[len(sorted)-1]
		rangeV := maxV - minV
		var bucketSize float64
		if rangeV != 0 {
			bucketSize = rangeV / float64(numBuckets-1)
		}

		labels := make([]float64, numBuckets)
		counts := make([]int, numBuckets)
		for i := 0; i < numBuckets; i++ {
			labels[i] = minV + float64(i)*bucketSize
		}

		for _, d := range durations {
			var idx int
			if rangeV == 0 {
				idx = 0
			} else {
				idx = int(math.Floor((d - minV) / bucketSize))
				if idx >= numBuckets {
					idx = numBuckets - 1
				}
				if idx < 0 {
					idx = 0
				}
			}
			counts[idx]++
		}

		for i, label := range labels {
			histMap[strconv.FormatFloat(label, 'f', -1, 64)] = counts[i]
		}
	}

	// Percentiles
	sortedD := make([]float64, len(durations))
	copy(sortedD, durations)
	sort.Float64s(sortedD)

	p10 := percentile(sortedD, 10)
	p25 := percentile(sortedD, 25)
	p50 := percentile(sortedD, 50)
	p75 := percentile(sortedD, 75)
	p90 := percentile(sortedD, 90)
	p95 := percentile(sortedD, 95)
	p99 := percentile(sortedD, 99)
	p999 := percentile(sortedD, 99.9)
	p9999 := percentile(sortedD, 99.99)

	// RPS stats
	rpsStats := computeRPSStats(result)

	// DNS details
	var dialupTimes, lookupTimes []float64
	for _, r := range result.Results {
		if r.HasStatus {
			dialupTimes = append(dialupTimes, r.DNSDialup)
			lookupTimes = append(lookupTimes, r.DNSLookup)
		}
	}
	diaMin, diaMax, diaAvg := computeStats(dialupTimes)
	lookMin, lookMax, lookAvg := computeStats(lookupTimes)

	// Status distribution
	statusDist := make(map[string]int)
	for _, r := range result.Results {
		if r.HasStatus {
			statusDist[strconv.Itoa(r.Status)]++
		}
	}

	// Error distribution
	errDist := make(map[string]int)
	for _, r := range result.Results {
		if !r.HasStatus && r.Error != "" {
			errDist[r.Error]++
		}
	}

	output := map[string]interface{}{
		"summary": map[string]interface{}{
			"successRate":    successRate,
			"total":          total,
			"slowest":        maxD,
			"fastest":        minD,
			"average":        avgD,
			"requestsPerSec": requestsPerSec,
			"totalData":      int(totalBytes),
			"sizePerRequest": int(sizePerReq),
			"sizePerSec":     sizePerSec,
		},
		"responseTimeHistogram": histMap,
		"latencyPercentiles": map[string]interface{}{
			"p10":   p10,
			"p25":   p25,
			"p50":   p50,
			"p75":   p75,
			"p90":   p90,
			"p95":   p95,
			"p99":   p99,
			"p99.9": p999,
			"p99.99": p9999,
		},
		"rps": rpsStats,
		"details": map[string]interface{}{
			"DNSDialup": map[string]interface{}{
				"average": diaAvg,
				"fastest": diaMin,
				"slowest": diaMax,
			},
			"DNSLookup": map[string]interface{}{
				"average": lookAvg,
				"fastest": lookMin,
				"slowest": lookMax,
			},
		},
		"statusCodeDistribution": statusDist,
		"errorDistribution":      errDist,
	}

	data, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func computeRPSStats(result *LoadTestResult) map[string]interface{} {
	total := result.TotalDuration
	if total <= 0 || len(result.Results) == 0 {
		return map[string]interface{}{
			"mean": 0.0, "stddev": 0.0, "max": 0.0, "min": 0.0,
			"percentiles": map[string]interface{}{},
		}
	}

	nSeconds := int(math.Ceil(total)) + 1
	if nSeconds < 1 {
		nSeconds = 1
	}
	perSecond := make([]float64, nSeconds)

	for _, r := range result.Results {
		if r.HasStatus {
			sec := int(math.Floor(r.StartTime))
			if sec < len(perSecond) {
				perSecond[sec]++
			}
		}
	}

	var rpsVals []float64
	for _, v := range perSecond {
		if v > 0 {
			rpsVals = append(rpsVals, v)
		}
	}

	if len(rpsVals) == 0 {
		return map[string]interface{}{
			"mean": 0.0, "stddev": 0.0, "max": 0.0, "min": 0.0,
			"percentiles": map[string]interface{}{},
		}
	}

	mean := 0.0
	for _, v := range rpsVals {
		mean += v
	}
	mean /= float64(len(rpsVals))

	variance := 0.0
	for _, v := range rpsVals {
		variance += (v - mean) * (v - mean)
	}
	variance /= float64(len(rpsVals))
	stddev := math.Sqrt(variance)

	maxRPS := rpsVals[0]
	minRPS := rpsVals[0]
	for _, v := range rpsVals {
		if v > maxRPS {
			maxRPS = v
		}
		if v < minRPS {
			minRPS = v
		}
	}

	sort.Float64s(rpsVals)

	return map[string]interface{}{
		"mean":   mean,
		"stddev": stddev,
		"max":    maxRPS,
		"min":    minRPS,
		"percentiles": map[string]interface{}{
			"p10":   percentile(rpsVals, 10),
			"p25":   percentile(rpsVals, 25),
			"p50":   percentile(rpsVals, 50),
			"p75":   percentile(rpsVals, 75),
			"p90":   percentile(rpsVals, 90),
			"p95":   percentile(rpsVals, 95),
			"p99":   percentile(rpsVals, 99),
			"p99.9": percentile(rpsVals, 99.9),
			"p99.99": percentile(rpsVals, 99.99),
		},
	}
}

func formatCSV(result *LoadTestResult) string {
	var buf strings.Builder
	w := csv.NewWriter(&buf)
	w.Write([]string{"request-start", "DNS", "DNS+dialup", "Response-delay", "request-duration", "bytes", "status"})
	for _, r := range result.Results {
		if r.HasStatus {
			w.Write([]string{
				strconv.FormatFloat(r.StartTime, 'f', -1, 64),
				strconv.FormatFloat(r.DNSLookup, 'f', -1, 64),
				strconv.FormatFloat(r.DNSDialup, 'f', -1, 64),
				strconv.FormatFloat(r.ResponseDelay, 'f', -1, 64),
				strconv.FormatFloat(r.Duration, 'f', -1, 64),
				strconv.FormatInt(r.Bytes, 10),
				strconv.Itoa(r.Status),
			})
		}
	}
	w.Flush()
	return buf.String()
}

func debugRequest(cfg *Config) error {
	client, err := buildClient(cfg)
	if err != nil {
		return err
	}

	req, err := buildRequest(cfg, cfg.URL, nil)
	if err != nil {
		return err
	}

	version := "HTTP/1.1"
	if cfg.HTTP2 || cfg.HTTPVersion == "2" {
		version = "HTTP/2.0"
	}

	fmt.Printf("Request {\n")
	fmt.Printf("    method: %s,\n", req.Method)
	fmt.Printf("    uri: %s,\n", req.URL.RequestURI())
	fmt.Printf("    version: %s,\n", version)
	fmt.Printf("    headers: {\n")
	// Print headers in a specific order
	headerNames := []string{"accept", "accept-encoding", "user-agent", "host"}
	printedHeaders := make(map[string]bool)
	for _, name := range headerNames {
		val := req.Header.Get(name)
		if val == "" && name == "host" {
			val = req.Host
			if val == "" {
				val = req.URL.Host
			}
		}
		if val != "" {
			fmt.Printf("        %q: %q,\n", name, val)
			printedHeaders[strings.ToLower(name)] = true
		}
	}
	for name, vals := range req.Header {
		lname := strings.ToLower(name)
		if !printedHeaders[lname] {
			fmt.Printf("        %q: %q,\n", lname, vals[0])
		}
	}
	fmt.Printf("    },\n")
	fmt.Printf("    body: Full {\n")
	fmt.Printf("        data: None,\n")
	fmt.Printf("    },\n")
	fmt.Printf("}\n")

	// Make the actual request
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)

	respVersion := "HTTP/1.1"
	if resp.Proto == "HTTP/2.0" {
		respVersion = "HTTP/2.0"
	}

	fmt.Printf("Response {\n")
	fmt.Printf("    status: %d,\n", resp.StatusCode)
	fmt.Printf("    version: %s,\n", respVersion)
	fmt.Printf("    headers: {\n")
	// Print response headers
	for name, vals := range resp.Header {
		fmt.Printf("        %q: %q,\n", strings.ToLower(name), vals[0])
	}
	fmt.Printf("    },\n")
	fmt.Printf("    body: %s,\n", formatBodyDebug(body))
	fmt.Printf("}\n")

	return nil
}

