package randregex

import (
	"fmt"
	"math/rand"
	"regexp/syntax"
	"strings"
	"time"
	"unicode"
)

var rng = rand.New(rand.NewSource(time.Now().UnixNano()))
var rngMu sync.Mutex

// Regex holds a compiled regex for random generation
type Regex struct {
	prog *syntax.Regexp
	maxRepeat int
}

// New creates a new Regex from the given pattern
// maxRepeat limits the number of repetitions for unbounded quantifiers
func New(pattern string, maxRepeat int) (*Regex, error) {
	// Replace . with [^\n] to disable dot matching newlines (as in rand_regex)
	// Actually, in the original oha, "dot is disabled", meaning . is treated literally or not used
	// Let's parse with Perl syntax but override dot behavior
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil {
		return nil, err
	}
	re = re.Simplify()
	return &Regex{prog: re, maxRepeat: maxRepeat}, nil
}

// Generate generates a random string matching the regex
func (r *Regex) Generate() (string, error) {
	var sb strings.Builder
	if err := generateFromRegexp(&sb, r.prog, r.maxRepeat); err != nil {
		return "", err
	}
	return sb.String(), nil
}

func generateFromRegexp(sb *strings.Builder, re *syntax.Regexp, maxRepeat int) error {
	switch re.Op {
	case syntax.OpLiteral:
		for _, r := range re.Rune {
			sb.WriteRune(r)
		}
	case syntax.OpCharClass:
		// Pick a random rune from the class
		r := pickFromCharClass(re.Rune)
		sb.WriteRune(r)
	case syntax.OpAnyChar, syntax.OpAnyCharNotNL:
		// Generate a printable ASCII character
		ch := rune(rand.Intn(95) + 32) // 32-126
		sb.WriteRune(ch)
	case syntax.OpStar:
		n := rand.Intn(maxRepeat + 1)
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpPlus:
		n := rand.Intn(maxRepeat) + 1
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpQuest:
		if rand.Intn(2) == 1 {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpRepeat:
		min := re.Min
		max := re.Max
		if max == -1 {
			max = min + maxRepeat
		}
		var n int
		if max <= min {
			n = min
		} else {
			n = min + rand.Intn(max-min+1)
		}
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpConcat:
		for _, sub := range re.Sub {
			if err := generateFromRegexp(sb, sub, maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpAlternate:
		idx := rand.Intn(len(re.Sub))
		if err := generateFromRegexp(sb, re.Sub[idx], maxRepeat); err != nil {
			return err
		}
	case syntax.OpCapture:
		if len(re.Sub) > 0 {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpEmptyMatch:
		// nothing
	case syntax.OpBeginText, syntax.OpEndText, syntax.OpBeginLine, syntax.OpEndLine:
		// anchors, skip
	case syntax.OpWordBoundary, syntax.OpNoWordBoundary:
		// skip
	case syntax.OpNoMatch:
		return fmt.Errorf("no match possible")
	default:
		return fmt.Errorf("unsupported regex op: %v", re.Op)
	}
	return nil
}

func pickFromCharClass(runes []rune) rune {
	// runes is pairs of [lo, hi] ranges
	// Count total chars
	total := 0
	for i := 0; i+1 < len(runes); i += 2 {
		total += int(runes[i+1]-runes[i]) + 1
	}
	if total == 0 {
		return 'a'
	}
	n := rand.Intn(total)
	for i := 0; i+1 < len(runes); i += 2 {
		rangeSize := int(runes[i+1]-runes[i]) + 1
		if n < rangeSize {
			return runes[i] + rune(n)
		}
		n -= rangeSize
	}
	return runes[0]
}

