		max := re.Max
		if max == -1 {
			max = min + maxRepeat
		}
		var n int
		if max <= min {
			n = min
		} else {
			n = min + rng.Intn(max-min+1)
		}
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpConcat:
		for _, sub := range re.Sub {
			if err := generateFromRegexp(sb, sub, maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpAlternate:
		idx := rng.Intn(len(re.Sub))
		if err := generateFromRegexp(sb, re.Sub[idx], maxRepeat); err != nil {
			return err
		}
	case syntax.OpCapture:
		if len(re.Sub) > 0 {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpEmptyMatch:
		// nothing
	case syntax.OpBeginText, syntax.OpEndText, syntax.OpBeginLine, syntax.OpEndLine:
		// anchors, skip
	case syntax.OpWordBoundary, syntax.OpNoWordBoundary:
		// skip
	case syntax.OpNoMatch:
		return fmt.Errorf("no match possible")
	default:
		return fmt.Errorf("unsupported regex op: %v", re.Op)
	}
	return nil
}

func pickFromCharClass(runes []rune) rune {
	total := 0
	for i := 0; i+1 < len(runes); i += 2 {
		total += int(runes[i+1]-runes[i]) + 1
	}
	if total == 0 {
		return 'a'
	}
	n := rng.Intn(total)
	for i := 0; i+1 < len(runes); i += 2 {
		rangeSize := int(runes[i+1]-runes[i]) + 1
		if n < rangeSize {
			return runes[i] + rune(n)
		}
		n -= rangeSize
	}
	return runes[0]
}
