// Regex holds a compiled regex for random generation
type Regex struct {
	prog      *syntax.Regexp
	maxRepeat int
}

// New creates a new Regex from the given pattern
func New(pattern string, maxRepeat int) (*Regex, error) {
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil {
		return nil, err
	}
	re = re.Simplify()
	return &Regex{prog: re, maxRepeat: maxRepeat}, nil
}

// Generate generates a random string matching the regex
func (r *Regex) Generate() (string, error) {
	rngMu.Lock()
	defer rngMu.Unlock()
	var sb strings.Builder
	if err := generateFromRegexp(&sb, r.prog, r.maxRepeat); err != nil {
		return "", err
	}
	return sb.String(), nil
}

