func buildHistogramEntries(durations []float64) []histEntry {
	const numBuckets = 11

	if len(durations) == 0 {
		return nil
	}

	sorted := make([]float64, len(durations))
	copy(sorted, durations)
	sort.Float64s(sorted)

	minV := sorted[0]
	maxV := sorted[len(sorted)-1]
	rangeV := maxV - minV
	var bucketSize float64
	if rangeV != 0 {
		bucketSize = rangeV / float64(numBuckets-1)
	}

	labels := make([]float64, numBuckets)
	counts := make([]int, numBuckets)
	for i := 0; i < numBuckets; i++ {
		labels[i] = minV + float64(i)*bucketSize
	}

	for _, d := range durations {
		var idx int
		if rangeV == 0 {
			idx = 0
		} else {
			idx = int(math.Floor((d - minV) / bucketSize))
			if idx >= numBuckets {
				idx = numBuckets - 1
			}
			if idx < 0 {
				idx = 0
			}
		}
		counts[idx]++
	}

	entries := make([]histEntry, numBuckets)
	for i := range labels {
		entries[i] = histEntry{labels[i], counts[i]}
	}
	return entries
}

