# So the histogram only shows successful request durations
# But the auto-unit still shows "ns" despite NaN averages!

# I think oha uses the FASTEST/SLOWEST of ALL requests (including failures) for auto-unit
# OR it defaults to "ns" when all requests fail

# Let me check with a mix of success and failure
# If auto-unit uses failed durations too, those fast failures would pick "ns" even with some successes

# Actually, looking at the structure: oha probably calculates auto-unit based on 
# whether there ARE successful responses or not:
# - If no successful responses: use "ns" (or maybe default)  
# - If there are successful responses: use based on average

# Let me update my autoTimeUnit function to handle the NaN case:
python3 << 'EOF'
with open('/workspace/oha_go/main.go', 'r') as f:
    content = f.read()

old = '''func autoTimeUnit(avgSeconds float64) TimeUnit {
	if math.IsNaN(avgSeconds) || avgSeconds <= 0 {
		return TimeUnitMs
	}
	if avgSeconds < 1e-6 {
		return TimeUnitNs
	}
	if avgSeconds < 1e-3 {
		return TimeUnitUs
	}
	if avgSeconds < 1.0 {
		return TimeUnitMs
	}
	if avgSeconds < 60.0 {
		return TimeUnitS
	}
	return TimeUnitM
}'''

