func New(pattern string, maxRepeat int) (*Regex, error) {
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil {
		return nil, err
	}
	re = re.Simplify()
	return &Regex{prog: re, maxRepeat: maxRepeat}, nil
}'''

new_new = '''// New creates a new Regex from the given pattern
// Note: dot is disabled - "." in pattern is treated as literal dot, not any-char
func New(pattern string, maxRepeat int) (*Regex, error) {
	// Escape literal dots (that are not inside character classes)
	// to disable the dot-matches-any behavior
	escapedPattern := escapeDots(pattern)
	re, err := syntax.Parse(escapedPattern, syntax.Perl)
	if err != nil {
		return nil, err
	}
	re = re.Simplify()
	return &Regex{prog: re, maxRepeat: maxRepeat}, nil
}

// escapeDots escapes literal dots that are outside character classes
// to implement "dot is disabled" behavior
func escapeDots(pattern string) string {
	var result strings.Builder
	inClass := false
	escaped := false

	for _, ch := range pattern {
		if escaped {
			result.WriteRune(ch)
			escaped = false
			continue
		}

		switch ch {
		case \\'\\\\\\':
			result.WriteRune(ch)
			escaped = true
		case \\'[\\':\\
			inClass = true
			result.WriteRune(ch)
		case \\']\\':
			inClass = false
			result.WriteRune(ch)
		case \\'.\\':
			if inClass {
				result.WriteRune(ch)
			} else {
				// Escape the dot to make it literal
				result.WriteString("\\\\.")
			}
		default:
			result.WriteRune(ch)
		}
	}

	return result.String()
}'''

