cat > /workspace/oha_go/internal/randregex/randregex.go << 'GOEOF'
package randregex

import (
	"fmt"
	"math/rand"
	"regexp/syntax"
	"strings"
	"sync"
	"time"
)

var rng = rand.New(rand.NewSource(time.Now().UnixNano()))
var rngMu sync.Mutex

// Regex holds a compiled regex for random generation
type Regex struct {
	prog      *syntax.Regexp
	maxRepeat int
}

// escapeDots escapes literal dots that are outside character classes
// to implement "dot is disabled" behavior (dots match only '.' not any character)
func escapeDots(pattern string) string {
	var result strings.Builder
	inClass := false
	escaped := false

	for _, ch := range pattern {
		if escaped {
			result.WriteRune(ch)
			escaped = false
			continue
		}

		switch ch {
		case '\\':
			result.WriteRune(ch)
			escaped = true
		case '[':
			inClass = true
			result.WriteRune(ch)
		case ']':
			inClass = false
			result.WriteRune(ch)
		case '.':
			if inClass {
				result.WriteRune(ch)
			} else {
				// Escape the dot to make it match only literal '.'
				result.WriteString("\\.")
			}
		default:
			result.WriteRune(ch)
		}
	}

	return result.String()
}

// New creates a new Regex from the given pattern
// Note: dot is disabled - "." in pattern is treated as literal dot, not any-char
func New(pattern string, maxRepeat int) (*Regex, error) {
	// Escape literal dots (that are not inside character classes)
	// to implement "dot is disabled" behavior
	escapedPattern := escapeDots(pattern)
	re, err := syntax.Parse(escapedPattern, syntax.Perl)
	if err != nil {
		return nil, err
	}
	re = re.Simplify()
	return &Regex{prog: re, maxRepeat: maxRepeat}, nil
}

// Generate generates a random string matching the regex
func (r *Regex) Generate() (string, error) {
	rngMu.Lock()
	defer rngMu.Unlock()
	var sb strings.Builder
	if err := generateFromRegexp(&sb, r.prog, r.maxRepeat); err != nil {
		return "", err
	}
	return sb.String(), nil
}

func generateFromRegexp(sb *strings.Builder, re *syntax.Regexp, maxRepeat int) error {
	switch re.Op {
	case syntax.OpLiteral:
		for _, r := range re.Rune {
			sb.WriteRune(r)
		}
	case syntax.OpCharClass:
		r := pickFromCharClass(re.Rune)
		sb.WriteRune(r)
	case syntax.OpAnyChar, syntax.OpAnyCharNotNL:
		ch := rune(rng.Intn(95) + 32)
		sb.WriteRune(ch)
	case syntax.OpStar:
		n := rng.Intn(maxRepeat + 1)
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpPlus:
		n := rng.Intn(maxRepeat) + 1
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpQuest:
		if rng.Intn(2) == 1 {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpRepeat:
		min := re.Min
		max := re.Max
		if max == -1 {
			max = min + maxRepeat
		}
		var n int
		if max <= min {
			n = min
		} else {
			n = min + rng.Intn(max-min+1)
		}
		for i := 0; i < n; i++ {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpConcat:
		for _, sub := range re.Sub {
			if err := generateFromRegexp(sb, sub, maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpAlternate:
		idx := rng.Intn(len(re.Sub))
		if err := generateFromRegexp(sb, re.Sub[idx], maxRepeat); err != nil {
			return err
		}
	case syntax.OpCapture:
		if len(re.Sub) > 0 {
			if err := generateFromRegexp(sb, re.Sub[0], maxRepeat); err != nil {
				return err
			}
		}
	case syntax.OpEmptyMatch:
		// nothing
	case syntax.OpBeginText, syntax.OpEndText, syntax.OpBeginLine, syntax.OpEndLine:
		// anchors, skip
	case syntax.OpWordBoundary, syntax.OpNoWordBoundary:
		// skip
	case syntax.OpNoMatch:
		return fmt.Errorf("no match possible")
	default:
		return fmt.Errorf("unsupported regex op: %v", re.Op)
	}
	return nil
}

func pickFromCharClass(runes []rune) rune {
	total := 0
	for i := 0; i+1 < len(runes); i += 2 {
		total += int(runes[i+1]-runes[i]) + 1
	}
	if total == 0 {
		return 'a'
	}
	n := rng.Intn(total)
	for i := 0; i+1 < len(runes); i += 2 {
		rangeSize := int(runes[i+1]-runes[i]) + 1
		if n < rangeSize {
			return runes[i] + rune(n)
		}
		n -= rangeSize
	}
	return runes[0]
}
